window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[312]={"id":"312","numero":312,"titre":"Tumeurs du sein","objectifs":[{"id":"312-1","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l'épidémiologie des tumeurs du sein","contenu":"<div class=\"notion-course\"><p>Le <span class=\"nc-red_bg\">cancer du sein</span> est le <span><span class=\"nc-yellow_bg\">cancer le plus fréquent chez la femme</span></span> en France et le <span>2ème cancer tous sexes confondus</span>. Il représente la <span><span class=\"nc-red nc-bold\">1ère cause de mortalité par cancer chez la femme</span></span>, malgré une <span><span class=\"nc-green_bg\">mortalité</span></span><span class=\"nc-green_bg\"> en diminution</span> grâce au <span>dépistage</span> et aux <span>progrès thérapeutiques</span>.</p>\n      <table>\n        <thead>\n          <tr><th>Paramètre</th><th>Valeur (France)</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span>Incidence</span> (2018)</td><td><span>~58 500 nouveaux cas/an</span> — <span><span class=\"nc-red_bg\">incidence</span></span><span class=\"nc-red_bg\"> en augmentation</span></td></tr>\n          <tr><td><span>Prévalence</span></td><td><span>650 000 à 900 000</span> femmes</td></tr>\n          <tr><td>Risque cumulé vie entière</td><td><span>~1 femme sur 8 à 10</span> développera un <span class=\"nc-red_bg\">cancer du sein</span></td></tr>\n          <tr><td>Âge médian au diagnostic</td><td><span><span class=\"nc-pink nc-bold\">63 ans</span></span> — moitié des cas entre <span>45 et 65 ans</span></td></tr>\n          <tr><td>Âge médian au décès</td><td><span><span class=\"nc-pink nc-bold\">74 ans</span></span></td></tr>\n          <tr><td><span>Mortalité</span> (2018)</td><td><span>~12 000 décès/an</span> — en diminution</td></tr>\n          <tr><td><span class=\"nc-green_bg nc-bold\">Survie</span> <span class=\"nc-green_bg nc-bold\">globale</span> à <span>5 ans</span></td><td><span>~90 %</span> (forte hétérogénéité selon sous-type et <span>stade</span>)</td></tr>\n          <tr><td>Sexe</td><td><span>&gt; 99 %</span> des cas chez la femme — existe chez l'homme (rare)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> 1<sup>er</sup> en <span>incidence</span> + <span><span class=\"nc-red nc-bold\">1</span><sup><span class=\"nc-red nc-bold\">ère</span></sup><span class=\"nc-red nc-bold\"> cause de mortalité par cancer chez la femme</span></span>. Couple incidence ↑ / <span class=\"nc-green nc-bold\">mortalité</span> ↓ = succès du <span>dépistage organisé</span> (<span><span class=\"nc-pink nc-bold\">50-74 ans</span></span>) et des <span>thérapies ciblées</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — Epidémiologie cancers</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li></ul></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/fibroadenoma-breast","label":"Radiopaedia : Fibroadenoma breast"},{"href":"https://radiopaedia.org/articles/fibrocystic-change-breast","label":"Radiopaedia : Fibrocystic change breast"},{"href":"https://radiopaedia.org/articles/phyllodes-tumour-1","label":"Radiopaedia : Phyllodes tumour 1"},{"href":"https://radiopaedia.org/articles/intraductal-papilloma-of-breast","label":"Radiopaedia : Intraductal papilloma of breast"},{"href":"https://radiopaedia.org/articles/breast-hamartoma","label":"Radiopaedia : Breast hamartoma"},{"href":"https://radiopaedia.org/articles/fat-necrosis-breast-2","label":"Radiopaedia : Fat necrosis breast"},{"href":"https://radiopaedia.org/articles/breast-neoplasms","label":"Radiopaedia : Breast neoplasms"},{"href":"https://radiopaedia.org/articles/breast","label":"Radiopaedia : Breast"},{"href":"https://radiopaedia.org/articles/breast-imaging-reporting-and-data-system-bi-rads","label":"Radiopaedia : Breast imaging reporting and data system bi rads"},{"href":"https://radiopaedia.org/articles/breast-ultrasound-1","label":"Radiopaedia : Breast ultrasound 1"},{"href":"http://radiopaedia.org","label":"radiopaedia.org"}]},{"id":"312-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les facteurs de risque des tumeurs du sein","contenu":"<div class=\"notion-course\"><p>Maladie <span>multifactorielle</span> : l'âge, l'exposition hormonale endogène et exogène, les antécédents personnels et familiaux et le mode de vie se combinent. L'identification du niveau de risque guide la <span>stratégie de dépistage</span> (organisé, individuel, ou très ciblé pour les <span>mutations délétères</span>).</p>\n      <table>\n        <thead>\n          <tr><th>Catégorie</th><th><span>Facteurs de risque</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Âge</td>\n            <td><span>Moitié des cas entre 45 et 65 ans</span> — l'âge est le <span>FDR principal</span> de la population générale.</td>\n          </tr>\n          <tr>\n            <td>Exposition hormonale</td>\n            <td>\n              <strong>Imprégnation œstrogénique longue :</strong>\n              <ul>\n                <li>Puberté précoce (<span>&lt; 12 ans</span>)</li>\n                <li>Ménopause tardive (<span>&gt; 55 ans</span>)</li>\n                <li>1<sup>ère</sup> <span>grossesse</span> tardive (<span>&gt; 30 ans</span>)</li>\n                <li><span>Pauciparité, nulliparité</span></li>\n                <li><span><span class=\"nc-green_bg\">Absence d'allaitement</span></span></li>\n              </ul>\n              <strong>Traitements hormonaux :</strong>\n              <ul>\n                <li><span>Contraception œstro-progestative</span> (RR <span>1,04</span> — sur-risque faible)</li>\n                <li><span>THM</span> dépend du schéma et de la durée</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td>ATCD personnels</td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-orange_bg\">Carcinome in situ</span></span> (CCIS ou CLIS)</li>\n                <li><span><span class=\"nc-orange_bg\">Hyperplasie atypique</span></span> (canalaire ou lobulaire)</li>\n                <li><span><span class=\"nc-yellow_bg\">Mastopathie à risque histologique</span></span></li>\n                <li><span>Radiothérapie thoracique haute dose</span> (Hodgkin avant <span>30 ans</span>)</li>\n                <li><span>ATCD personnel de <span class=\"nc-red_bg\">cancer du sein</span></span> : <span>terrain</span> croisé avec cancers de l'<span>endomètre</span> et de l'<span><span class=\"nc-orange nc-bold\">ovaire</span></span> (mutations BRCA) → <span><span class=\"nc-red nc-bold\">examen gynécologique systématique</span></span> à toute <span>consultation de suivi</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td>ATCD familiaux</td>\n            <td>Tenir compte du degré de parenté, de l'âge de survenue, de la bilatéralité et de la multifocalité. Le <span>score d'Eisinger</span> gradue le risque familial : <span>≥ 3</span> = indication formelle de <span>consultation d'oncogénétique</span>.</td>\n          </tr>\n          <tr>\n            <td><span>Génétique</span></td>\n            <td><span>Syndrome sein-<span class=\"nc-orange nc-bold\">ovaire</span></span> (BRCA1/2,<span> 5-10 %</span> des cancers du sein) ; autres : <em><span class=\"nc-red_bg nc-bold\">TP53</span></em> (Li-Fraumeni), <em>CDH1</em>, <em>PALB2</em>, <em>CHEK2</em>, <em>ATM</em>, <em>PTEN</em> (Cowden), <em>STK11</em> (Peutz-Jeghers).</td>\n          </tr>\n          <tr>\n            <td>Mode de vie</td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-yellow_bg\">Alcool</span></span>, <span>tabac</span></li>\n                <li><span><span class=\"nc-yellow_bg\">Surpoids / obésité</span></span> (surtout post-ménopause)</li>\n                <li><span><span class=\"nc-blue_bg\">Sédentarité</span></span></li>\n                <li><span class=\"nc-blue_bg\">Haut niveau socio-économique</span> (biais de <span>dépistage</span>)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le sur-risque attribué à la contraception œstro-progestative est <span>faible</span> (RR 1,04) et ne contre-indique pas la prescription chez une femme sans autre FDR. À l'inverse, une <span>irradiation thoracique pour maladie de Hodgkin avant 30 ans</span> impose un <span>dépistage</span> individuel renforcé (mammo + <span>IRM</span> annuelles dès <span>30 ans</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li></ul></details>","frequence":3},{"id":"312-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les prédispositions génétiques du cancer du sein","contenu":"<div class=\"notion-course\"><p>Les prédispositions héréditaires expliquent <span>5-10 %</span> des cancers du <span class=\"nc-orange nc-bold\">sein</span> et <span>20 %</span> des cancers du <span class=\"nc-orange nc-bold\">sein</span> familiaux. La mutation la plus fréquente porte sur les gènes <span>BRCA1</span> (chromosome 17) et <span>BRCA2</span> (chromosome 13), <span>gènes suppresseurs de tumeurs</span> codant pour des protéines de la <span>réparation de l'ADN par recombinaison homologue</span>. Transmission <span>autosomique dominante</span>.</p>\n      <table>\n        <thead>\n          <tr><th>Item</th><th>BRCA1 / BRCA2</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Mode de transmission</td><td>Autosomique dominante</td></tr>\n          <tr><td>Mécanisme</td><td>Hétérozygotie constitutionnelle + 2<sup>e</sup> mutation somatique sur le brin sain → déficit de la réparation des cassures double-brin → phénotype <span>HRD</span> (<em>Homologous Recombination Deficient</em>)</td></tr>\n          <tr><td>Risque cumulé <span class=\"nc-red_bg\">cancer du sein</span></td><td><span>60-80 %</span> (âge précoce, <span class=\"nc-pink nc-bold\">multifocal</span>, bilatéral fréquents)</td></tr>\n          <tr><td>Risque cumulé cancer de l'<span class=\"nc-orange nc-bold\">ovaire</span></td><td><span>~60 %</span> (BRCA1) ; <span>~30 %</span> (BRCA2)</td></tr>\n          <tr><td>Autres cancers (BRCA2)</td><td><span>Mélanome</span>, pancréas, prostate, sein chez l'<span class=\"nc-pink nc-bold\">homme</span></td></tr>\n        </tbody>\n      </table>\n      <h4>Indications d'oncogénétique (cas-index) — ATCD personnels</h4>\n      <table>\n        <thead>\n          <tr><th>Critère</th><th>Pourquoi suspect</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"nc-red_bg\">Cancer du sein</span> <span><span class=\"nc-pink nc-bold\">≤ 40 ans</span></span></td><td>Survenue jeune = forte présomption <span>héréditaire</span></td></tr>\n          <tr><td>Sein + <span><span class=\"nc-orange nc-bold\">ovaire</span></span> chez la même patiente</td><td>Syndrome <span>sein-<span class=\"nc-orange nc-bold\">ovaire</span></span> (BRCA1/2)</td></tr>\n          <tr><td><span class=\"nc-red_bg\">Cancer du sein</span> <span><span class=\"nc-pink nc-bold\">multifocal</span></span> ou <span>bilatéral</span></td><td>Phénotype BRCA-like</td></tr>\n          <tr><td><span class=\"nc-red_bg\">Cancer du sein</span> chez l'<span><span class=\"nc-pink nc-bold\">homme</span></span></td><td>Évoque BRCA2</td></tr>\n          <tr><td><span class=\"nc-red_bg\">Cancer du sein</span> de type <span><span class=\"nc-red nc-bold\">médullaire</span></span></td><td>Forme histologique évocatrice de BRCA1</td></tr>\n          <tr><td><span><span class=\"nc-red nc-bold\">Triple négatif</span></span> avant <span>60 ans</span></td><td>Sous-type fortement associé à BRCA1</td></tr>\n        </tbody>\n      </table>\n      <p><strong>ATCD familiaux :</strong></p>\n      <ul>\n        <li><span>≥ 3</span> cancers du sein chez apparentées au 1<sup>er</sup> ou 2<sup>e</sup> degré</li>\n        <li><span>≥ 2</span> cancers du sein chez apparentées de <span><span class=\"nc-pink nc-bold\">&lt; 70 ans</span></span>, dont <span>≥ 1</span> à <span><span class=\"nc-pink nc-bold\">&lt; 50 ans</span></span></li>\n        <li><span>≥ 1</span> <span class=\"nc-red_bg\">cancer du sein</span> + 1 cancer de l'<span class=\"nc-orange nc-bold\">ovaire</span> au 1<sup>er</sup> degré</li>\n      </ul>\n      <h4>Mesures préventives en cas de mutation</h4>\n      <table>\n        <thead>\n          <tr><th>Mesure</th><th>Âge</th><th>Fréquence</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span>Examen clinique des seins</span></td><td>Dès <span>20 ans</span></td><td>Bisannuel</td></tr>\n          <tr><td><span>IRM mammaire</span> + <span>mammographie</span> (<span>incidence</span> oblique unique) ± écho</td><td><span>30 - 65 ans</span></td><td><span class=\"nc-pink nc-bold\">Annuelle</span></td></tr>\n          <tr><td><span>Mastectomie bilatérale prophylactique</span></td><td>Envisagée dès <span>30 ans</span></td><td>—</td></tr>\n          <tr><td><span>Surveillance</span> gynécologique ± écho pelvienne</td><td>Dès <span>30-35 ans</span></td><td><span class=\"nc-pink nc-bold\">Annuelle</span></td></tr>\n          <tr><td><span>Annexectomie bilatérale prophylactique</span></td><td>BRCA1 : <span>40-41 ans</span> ; BRCA2 : <span>45-47 ans</span></td><td>—</td></tr>\n        </tbody>\n      </table>\n      <h4>Intérêt thérapeutique : anti-PARP</h4>\n      <p>Les cancers BRCA-mutés sont <span>plus chimiosensibles</span> que les cancers sporadiques. La prescription des <span>inhibiteurs de PARP</span> (anti-PARP) est conditionnée à la présence d'une mutation BRCA (germinale ou somatique) dans les cancers du <strong><span class=\"nc-orange nc-bold\">sein</span></strong>, de la <strong>prostate</strong>, de l'<strong><span class=\"nc-orange nc-bold\">ovaire</span></strong> et du <strong>pancréas</strong>.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le <span>score d'Eisinger</span> (seuil <span>≥ 3</span>) déclenche la <span>consultation d'oncogénétique</span>. Le diagnostic d'une mutation conditionne à la fois la <span>surveillance individualisée</span>, la <span>chirurgie prophylactique</span> et la <span>prescription d'anti-PARP</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 306 — Tumeur ovaire · 300 — Tumeur col-corps utérin</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li></ul></details>","frequence":3},{"id":"312-4","rang":"A","rubrique":"Physiopathologie","titre":"Connaître l'histoire naturelle du cancer du sein et ses modes de dissémination","contenu":"<div class=\"notion-course\"><p>Le <span class=\"nc-red_bg\">cancer du sein</span> naît des cellules de l'<span>appareil sécrétoire</span> du sein (<span class=\"nc-green_bg\">lobules</span> et <span class=\"nc-green_bg\">canaux</span> galactophores). La <span>carcinogenèse</span> suit un processus multi-étapes (<span>initiation, promotion, progression</span>) sous l'influence des <span><span class=\"nc-pink_bg nc-bold\">œstrogènes</span></span> (<span>60-70 %</span> des cas — cancer hormono-dépendant).</p>\n      <figure class=\"obj-figure\">\n        <svg viewbox=\"0 0 760 360\" role=\"img\" aria-labelledby=\"t312o3 d312o3\" preserveaspectratio=\"xMidYMid meet\" style=\"display:block;width:100%;max-width:700px;height:auto;margin:0 auto\">\n          <title id=\"t312o3\">Histoire naturelle du cancer du sein</title>\n          <desc id=\"d312o3\">La cellule normale évolue en <span>carcinome</span> in situ (membrane basale intacte, sans métastase) puis, après franchissement de la membrane basale, en carcinome invasif qui dissémine par voie lymphatique et hématogène.</desc>\n          <defs>\n            <marker id=\"a312o3\" markerwidth=\"9\" markerheight=\"9\" refx=\"7\" refy=\"4.5\" orient=\"auto\"><path d=\"M0,0 L9,4.5 L0,9 z\" fill=\"var(--ink-muted)\"></path></marker>\n            <marker id=\"a312o3r\" markerwidth=\"9\" markerheight=\"9\" refx=\"7\" refy=\"4.5\" orient=\"auto\"><path d=\"M0,0 L9,4.5 L0,9 z\" fill=\"var(--spe-infectio)\"></path></marker>\n          </defs>\n          <rect x=\"20\" y=\"40\" width=\"150\" height=\"80\" rx=\"10\" fill=\"var(--ink-muted)\" opacity=\"0.12\"></rect>\n          <rect x=\"20\" y=\"40\" width=\"150\" height=\"80\" rx=\"10\" fill=\"none\" stroke=\"var(--ink-muted)\"></rect>\n          <text x=\"95\" y=\"74\" text-anchor=\"middle\" fill=\"var(--ink)\" font-size=\"13\" font-weight=\"600\">Cellule normale</text>\n          <text x=\"95\" y=\"94\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"11\">canal / lobule</text>\n          <line x1=\"170\" y1=\"80\" x2=\"242\" y2=\"80\" stroke=\"var(--ink-muted)\" stroke-width=\"2\" marker-end=\"url(#a312o3)\"></line>\n          <text x=\"206\" y=\"70\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10\">carcinogenèse</text>\n          <rect x=\"250\" y=\"40\" width=\"190\" height=\"80\" rx=\"10\" fill=\"var(--spe-pneumo)\" opacity=\"0.16\"></rect>\n          <rect x=\"250\" y=\"40\" width=\"190\" height=\"80\" rx=\"10\" fill=\"none\" stroke=\"var(--spe-pneumo)\"></rect>\n          <text x=\"345\" y=\"66\" text-anchor=\"middle\" fill=\"var(--ink)\" font-size=\"13\" font-weight=\"600\">Carcinome in situ</text>\n          <text x=\"345\" y=\"85\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\">membrane basale intacte</text>\n          <text x=\"345\" y=\"104\" text-anchor=\"middle\" fill=\"var(--spe-pneumo)\" font-size=\"11\" font-weight=\"700\">métastase NULLE</text>\n          <line x1=\"498\" y1=\"34\" x2=\"498\" y2=\"126\" stroke=\"var(--spe-infectio)\" stroke-width=\"1.5\" stroke-dasharray=\"5 4\"></line>\n          <line x1=\"440\" y1=\"80\" x2=\"560\" y2=\"80\" stroke=\"var(--spe-infectio)\" stroke-width=\"2.5\" marker-end=\"url(#a312o3r)\"></line>\n          <text x=\"500\" y=\"145\" text-anchor=\"middle\" fill=\"var(--spe-infectio)\" font-size=\"10\" font-weight=\"600\">franchit la membrane basale</text>\n          <rect x=\"570\" y=\"40\" width=\"170\" height=\"80\" rx=\"10\" fill=\"var(--spe-infectio)\" opacity=\"0.16\"></rect>\n          <rect x=\"570\" y=\"40\" width=\"170\" height=\"80\" rx=\"10\" fill=\"none\" stroke=\"var(--spe-infectio)\"></rect>\n          <text x=\"655\" y=\"74\" text-anchor=\"middle\" fill=\"var(--ink)\" font-size=\"13\" font-weight=\"600\">Carcinome invasif</text>\n          <text x=\"655\" y=\"94\" text-anchor=\"middle\" fill=\"var(--spe-infectio)\" font-size=\"11\" font-weight=\"700\">métastase +</text>\n          <line x1=\"655\" y1=\"120\" x2=\"410\" y2=\"172\" stroke=\"var(--ink-muted)\" stroke-width=\"2\" marker-end=\"url(#a312o3)\"></line>\n          <text x=\"398\" y=\"165\" text-anchor=\"middle\" fill=\"var(--ink)\" font-size=\"11\" font-weight=\"600\">Dissémination</text>\n          <line x1=\"400\" y1=\"174\" x2=\"235\" y2=\"196\" stroke=\"var(--ink-muted)\" stroke-width=\"1.5\"></line>\n          <line x1=\"400\" y1=\"174\" x2=\"525\" y2=\"196\" stroke=\"var(--ink-muted)\" stroke-width=\"1.5\"></line>\n          <rect x=\"110\" y=\"196\" width=\"250\" height=\"138\" rx=\"10\" fill=\"var(--spe-cardio)\" opacity=\"0.13\"></rect>\n          <rect x=\"110\" y=\"196\" width=\"250\" height=\"138\" rx=\"10\" fill=\"none\" stroke=\"var(--spe-cardio)\"></rect>\n          <text x=\"235\" y=\"222\" text-anchor=\"middle\" fill=\"var(--ink)\" font-size=\"12.5\" font-weight=\"700\">Voie lymphatique</text>\n          <text x=\"126\" y=\"250\" fill=\"var(--ink)\" font-size=\"11\">• Creux axillaire (relais princ.)</text>\n          <text x=\"126\" y=\"276\" fill=\"var(--ink)\" font-size=\"11\">• Sus- / sous-claviculaires</text>\n          <text x=\"126\" y=\"302\" fill=\"var(--ink)\" font-size=\"11\">• Chaîne mammaire interne</text>\n          <text x=\"126\" y=\"322\" fill=\"var(--ink-muted)\" font-size=\"10\">(non accessible à l'examen)</text>\n          <rect x=\"400\" y=\"196\" width=\"250\" height=\"138\" rx=\"10\" fill=\"var(--spe-infectio)\" opacity=\"0.13\"></rect>\n          <rect x=\"400\" y=\"196\" width=\"250\" height=\"138\" rx=\"10\" fill=\"none\" stroke=\"var(--spe-infectio)\"></rect>\n          <text x=\"525\" y=\"222\" text-anchor=\"middle\" fill=\"var(--ink)\" font-size=\"12.5\" font-weight=\"700\">Voie hématogène</text>\n          <text x=\"416\" y=\"250\" fill=\"var(--ink)\" font-size=\"11\">• Os</text>\n          <text x=\"416\" y=\"276\" fill=\"var(--ink)\" font-size=\"11\">• Poumon</text>\n          <text x=\"416\" y=\"302\" fill=\"var(--ink)\" font-size=\"11\">• Foie</text>\n          <text x=\"416\" y=\"322\" fill=\"var(--ink-muted)\" font-size=\"10\">+ SNC si HER2+ · péritoine si lobulaire</text>\n        </svg>\n        <figcaption>Le carcinome <strong>in situ</strong> ne métastase pas ; tout bascule au <strong>franchissement de la membrane basale</strong>, qui ouvre les voies lymphatique et hématogène.</figcaption>\n      </figure>\n      <h4>Étapes histologiques</h4>\n      <table>\n        <thead>\n          <tr><th>Étape</th><th><span><span class=\"nc-orange_bg\">Carcinome</span></span><span class=\"nc-orange_bg\"> in situ</span></th><th>Carcinome invasif (infiltrant)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Définition</td>\n            <td><span><span class=\"nc-green_bg\">Évolution</span></span> <span>intra-épithéliale</span> (contenu à l'intérieur du canal ou du lobule) — pas de <span class=\"nc-red nc-bold\">franchissement de la </span><span><span class=\"nc-red nc-bold\">membrane basale</span></span></td>\n            <td><span><span class=\"nc-red nc-bold\">Franchissement de la membrane basale</span></span></td>\n          </tr>\n          <tr>\n            <td>Risque métastatique</td>\n            <td><span>Nul</span> (pas de dissémination à distance)</td>\n            <td>Présent — <span>lymphatique</span> et <span>hématogène</span></td>\n          </tr>\n          <tr>\n            <td><span>Évolution</span></td>\n            <td>Dissémination canalaire dans le sein → <span class=\"nc-red_bg nc-bold\">mastectomie</span> souvent indiquée ; progression possible en plusieurs années vers un cancer invasif</td>\n            <td>Dissémination locale + ganglionnaire + à distance</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Modes de dissémination du <span>carcinome</span> invasif</h4>\n      <table>\n        <thead>\n          <tr><th>Voie</th><th>Sites concernés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span>Lymphatique</span></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-yellow_bg\">Ganglions du </span><strong><span class=\"nc-yellow_bg\">creux axillaire</span></strong> (relais principal)</li>\n                <li><span class=\"nc-purple_bg\">Ganglions</span> <strong>sus-</strong> et <strong>sous-claviculaires</strong></li>\n                <li><span class=\"nc-purple_bg\">Ganglions de la</span> <strong>chaîne mammaire interne</strong> (non accessibles à l'examen clinique)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span>Hématogène</span></td>\n            <td>\n              Sites préférentiels : <span>os</span>, <span><span class=\"nc-red nc-bold\">poumons</span></span>, <span><span class=\"nc-red nc-bold\">foie</span></span>.<br>\n              <span><span class=\"nc-red nc-bold\">Carcinose péritonéale et pleurale</span></span> : fréquente dans le <span><span class=\"nc-orange_bg\">carcinome</span></span><span class=\"nc-orange_bg\"> </span><strong><span class=\"nc-orange_bg\">lobulaire infiltrant</span></strong>.<br>\n              Métastases <span><span class=\"nc-red nc-bold\">cérébrales</span> (<span class=\"nc-red nc-bold\">SNC</span>)</span> : fréquence élevée dans le sous-type <strong>HER2+</strong>.<br>\n              Autres : <span>peau</span>, <span>ovaires</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Particularités évolutives selon sous-type moléculaire</h4>\n      <table>\n        <thead>\n          <tr><th>Sous-type</th><th>Particularité de dissémination / récidive</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span><span class=\"nc-orange_bg\">Carcinome lobulaire infiltrant</span></span></td>\n            <td>Tropisme <span>péritonéal et pleural</span> (carcinose) ; volontiers multifocal et bilatéral</td>\n          </tr>\n          <tr>\n            <td><span>HER2+</span></td>\n            <td>Tropisme <span>cérébral (SNC)</span> fréquent</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-red nc-bold\">Triple négatif</span></span></td>\n            <td>Récidive <span>précoce (<span class=\"nc-pink nc-bold\">2-3 premières années</span>)</span> ; mauvais <span>pronostic</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le <span><span class=\"nc-orange_bg\">carcinome</span></span><span class=\"nc-orange_bg\"> in situ</span> est <span>non métastasant</span> mais peut évoluer vers une forme invasive. Le <span class=\"nc-orange_bg\">carcinome </span><strong><span class=\"nc-orange_bg\">lobulaire</span></strong><span class=\"nc-orange_bg\"> infiltrant</span> a une dissémination volontiers <span>péritonéale</span> ; le sous-type <strong>HER2+</strong> a un tropisme <span>cérébral</span> ; les cancers <strong><span class=\"nc-red nc-bold\">triple</span> négatifs</strong> récidivent plus précocement (<span class=\"nc-pink nc-bold\">2-3 premières années</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 304 — Tumeur du foie · 309 — Tumeurs du poumon</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li></ul></details>","frequence":0},{"id":"312-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les différentes modalités de dépistage","contenu":"<div class=\"notion-course\"><p>L'<span><span class=\"nc-blue nc-bold\">examen clinique mammaire annuel</span></span> est recommandé chez toutes les femmes à partir de <span>25 ans</span>. La stratégie paraclinique dépend du niveau de risque : <span>dépistage organisé</span> pour la population générale, <span>dépistage individuel</span> pour les femmes à haut risque, et <span>programme personnalisé</span> pour les très hauts risques (BRCA1/2).</p>\n      <figure class=\"obj-figure\">\n        <svg viewbox=\"0 0 760 305\" role=\"img\" aria-labelledby=\"t312o4 d312o4\" preserveaspectratio=\"xMidYMid meet\" style=\"display:block;width:100%;max-width:660px;height:auto;margin:0 auto\">\n          <title id=\"t312o4\">Stratégie de <span>dépistage</span> selon le niveau de risque</title>\n          <desc id=\"d312o4\">Trois niveaux de risque en escalier : risque moyen (<span>mammographie</span> tous les <span>2 ans</span> de <span>50 à 74 ans</span>), risque élevé (<span>mammographie</span> et <span>échographie</span> annuelles) et très haut risque (<span>IRM</span>, <span>mammographie</span> et <span>échographie</span> annuelles dès <span>30 ans</span>).</desc>\n          <defs>\n            <marker id=\"a312o4\" markerwidth=\"9\" markerheight=\"9\" refx=\"7\" refy=\"4.5\" orient=\"auto\"><path d=\"M0,0 L9,4.5 L0,9 z\" fill=\"var(--ink-muted)\"></path></marker>\n          </defs>\n          <rect x=\"40\" y=\"190\" width=\"210\" height=\"80\" rx=\"10\" fill=\"var(--spe-pneumo)\" opacity=\"0.16\"></rect>\n          <rect x=\"40\" y=\"190\" width=\"210\" height=\"80\" rx=\"10\" fill=\"none\" stroke=\"var(--spe-pneumo)\"></rect>\n          <text x=\"56\" y=\"214\" fill=\"var(--spe-pneumo)\" font-size=\"13\" font-weight=\"700\">Risque moyen</text>\n          <text x=\"56\" y=\"234\" fill=\"var(--ink-muted)\" font-size=\"10.5\">Population générale</text>\n          <text x=\"56\" y=\"254\" fill=\"var(--ink)\" font-size=\"11\">Mammo ± écho · /<span>2 ans</span></text>\n          <text x=\"56\" y=\"268\" fill=\"var(--ink-muted)\" font-size=\"10\"><span>50–74 ans</span></text>\n          <rect x=\"270\" y=\"140\" width=\"210\" height=\"130\" rx=\"10\" fill=\"var(--spe-orl)\" opacity=\"0.16\"></rect>\n          <rect x=\"270\" y=\"140\" width=\"210\" height=\"130\" rx=\"10\" fill=\"none\" stroke=\"var(--spe-orl)\"></rect>\n          <text x=\"286\" y=\"164\" fill=\"var(--spe-orl)\" font-size=\"13\" font-weight=\"700\">Risque élevé</text>\n          <text x=\"286\" y=\"186\" fill=\"var(--ink-muted)\" font-size=\"10.5\">ATCD perso/fam., Hodgkin</text>\n          <text x=\"286\" y=\"210\" fill=\"var(--ink)\" font-size=\"11\">Mammo + <span>échographie</span></text>\n          <text x=\"286\" y=\"230\" fill=\"var(--ink-muted)\" font-size=\"10.5\">annuelle, à vie</text>\n          <rect x=\"500\" y=\"90\" width=\"210\" height=\"180\" rx=\"10\" fill=\"var(--spe-infectio)\" opacity=\"0.16\"></rect>\n          <rect x=\"500\" y=\"90\" width=\"210\" height=\"180\" rx=\"10\" fill=\"none\" stroke=\"var(--spe-infectio)\"></rect>\n          <text x=\"516\" y=\"116\" fill=\"var(--spe-infectio)\" font-size=\"13\" font-weight=\"700\">Très haut risque</text>\n          <text x=\"516\" y=\"138\" fill=\"var(--ink-muted)\" font-size=\"10.5\">BRCA1/2, TP53, PALB2…</text>\n          <text x=\"516\" y=\"162\" fill=\"var(--ink)\" font-size=\"11\">Examen clin. dès <span>20 ans</span></text>\n          <text x=\"516\" y=\"184\" fill=\"var(--ink)\" font-size=\"11\"><span>IRM</span> + mammo + écho /an</text>\n          <text x=\"516\" y=\"204\" fill=\"var(--ink-muted)\" font-size=\"10\"><span>30–65 ans</span></text>\n          <line x1=\"40\" y1=\"288\" x2=\"712\" y2=\"288\" stroke=\"var(--ink-muted)\" stroke-width=\"2\" marker-end=\"url(#a312o4)\"></line>\n          <text x=\"376\" y=\"302\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\">risque croissant → <span>surveillance</span> plus précoce, rapprochée et sensible</text>\n        </svg>\n        <figcaption>Plus le risque est élevé, plus la surveillance commence <strong>tôt</strong>, se fait <strong>rapprochée</strong> et gagne en sensibilité avec l'<strong><span>IRM</span></strong>.</figcaption>\n      </figure>\n      <h4>Trois niveaux de risque, trois stratégies</h4>\n      <table>\n        <thead>\n          <tr><th>Niveau de risque</th><th>Définition</th><th><span>Dépistage</span> paraclinique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-green nc-bold\">Risque moyen</span></strong></td>\n            <td>Toutes les femmes sans FDR particulier</td>\n            <td><strong><span>Dépistage</span> organisé :</strong><br><span><span class=\"nc-blue_bg\">Mammographie</span></span><span class=\"nc-blue_bg\"> bilatérale </span><span><span class=\"nc-blue_bg\">2 incidences</span></span> <br>Tous les <span><span class=\"nc-pink nc-bold\">2 ans</span></span> entre <span>50 et 74 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Haut risque (risque élevé)</strong></td>\n            <td>\n              <ul>\n                <li>Forme familiale avérée sans mutation identifiée</li>\n                <li>ATCD d'<span>irradiation thoracique haute dose</span> (Hodgkin)</li>\n                <li>ATCD personnel : <span><span class=\"nc-orange_bg\">hyperplasie atypique</span></span>, CLIS, CCIS, <span class=\"nc-red_bg\">cancer du sein</span></li>\n              </ul>\n            </td>\n            <td><strong><span>Dépistage</span> individuel :</strong><br><span><span class=\"nc-blue_bg\">Mammographie</span></span> + <span><span class=\"nc-blue_bg\">échographie</span></span> <span class=\"nc-pink nc-bold\">annuelle</span> <span class=\"nc-pink nc-bold\">à vie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Très haut risque</strong></td>\n            <td><span>Mutation délétère BRCA1/2</span> ou autres prédispositions (<span class=\"nc-red_bg nc-bold\">TP53</span>, PALB2…)</td>\n            <td><strong>Programme personnalisé :</strong> <span>examen clinique bisannuel</span> dès <span>20 ans</span> ; <span>IRM</span> + <span>mammographie</span> + écho annuelles entre <span>30-65 ans</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <h4><span>Dépistage</span> organisé du <span class=\"nc-red_bg\">cancer du sein</span></h4>\n      <p>Programme national instauré en <span>2004</span>. Invitation systématique par courrier de toutes les femmes de <span><span class=\"nc-yellow_bg nc-bold\">50-74 ans</span></span> sans FDR significatif autre que l'âge et <strong><span class=\"nc-green nc-bold\">sans signes cliniques</span></strong>.</p>\n      <table>\n        <thead>\n          <tr><th>Paramètre</th><th>Modalité</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Fréquence</strong></td><td>Tous les <span>2 ans</span></td></tr>\n          <tr><td><strong>Moyens</strong></td><td><span>Examen clinique mammaire</span> + <span><span class=\"nc-blue_bg\">mammographie</span></span><span class=\"nc-blue_bg\"> bilatérale avec </span><span><span class=\"nc-blue_bg\">2 incidences</span></span> (<em><span class=\"nc-blue nc-bold\">oblique externe</span></em> + <em>cranio-caudale</em>)</td></tr>\n          <tr><td><strong>2<sup>nde</sup> lecture systématique</strong></td><td>Mammographies <span>ACR 1 ou ACR 2</span> par un radiologue indépendant (lit ≥ <span>1500</span> mammographies supplémentaires/an)</td></tr>\n          <tr><td><strong>Prise en charge</strong></td><td><span>100 %</span> par l'assurance maladie</td></tr>\n          <tr><td><strong>Objectif</strong></td><td><span><span class=\"nc-pink nc-bold\">Réduction</span></span><span class=\"nc-pink nc-bold\"> de la </span><span><span class=\"nc-pink nc-bold\">mortalité</span></span><span class=\"nc-pink nc-bold\"> par cancer du sein</span></td></tr>\n          <tr><td><strong>Participation 2017</strong></td><td><span>~50 %</span> (insuffisant)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le <span>dépistage</span> organisé est <span>contre-indiqué chez les femmes symptomatiques</span> : devant tout signe clinique (<span>nodule</span>, <span>écoulement</span>, <span>rétraction</span>…), on bascule en <span>démarche diagnostique</span> et non en dépistage. Un dépistage ne se fait jamais sur un <span class=\"nc-orange nc-bold\">sein</span> malade.</div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li></ul></details>","frequence":3},{"id":"312-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les présentations cliniques des tumeurs du sein","contenu":"<div class=\"notion-course\"><p>L'examen des seins est <strong>bilatéral et comparatif</strong>, en position debout puis couchée, par <span>inspection puis palpation</span>. Tout signe clinique nouveau impose une démarche diagnostique (<span><span class=\"nc-blue_bg\">mammographie</span></span> ± <span><span class=\"nc-blue_bg\">échographie</span></span> ± <span>biopsie</span>). <span>L'apparition d'un nodule du sein chez une femme ménopausée doit faire suspecter un <span class=\"nc-red_bg\">cancer du sein</span> jusqu'à preuve du contraire.</span></p>\n      <h4>Signes cliniques par catégorie</h4>\n      <table>\n        <thead>\n          <tr><th>Catégorie</th><th>Signes</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Symptômes</td>\n            <td>\n              <ul>\n                <li><span>Douleur mammaire</span> (mastodynie)</li>\n                <li><span><span class=\"nc-blue_bg\">Écoulement mamelonnaire</span> suspect :</span> apparition <span class=\"nc-red nc-bold\">récente</span>, <strong><span class=\"nc-red nc-bold\">spontané</span></strong>, <strong><span class=\"nc-red nc-bold\">unilatéral</span></strong>, <strong><span class=\"nc-red nc-bold\">unipore</span></strong>, couleur <strong><span class=\"nc-red nc-bold\">claire</span></strong>, <strong><span class=\"nc-red nc-bold\">jaune</span> séreux</strong>, <strong><span class=\"nc-red nc-bold\">rouge</span> sanglant</strong> ou <strong><span class=\"nc-red nc-bold\">noir</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td>Modifications du sein</td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-blue_bg\">Ascension du sein</span>, asymétrie, augmentation de volume</span></li>\n                <li><span><span class=\"nc-yellow_bg\">Nodule / masse mammaire</span></span> — cancer jusqu'à preuve du contraire chez la femme ménopausée</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td>Modifications du mamelon</td>\n            <td>\n              <ul>\n                <li><span>Déviation</span>, <span>invagination</span> ou <span>rétraction</span> du mamelon</li>\n                <li><span class=\"nc-blue_bg\">Aspect </span><span><span class=\"nc-blue_bg\">eczématiforme</span></span><span class=\"nc-blue_bg\"> du mamelon</span> → évoque la <span><span class=\"nc-orange nc-bold\">maladie de Paget</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td>Modifications cutanées</td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-blue_bg\">Rétraction cutanée</span></span>, <span>fossette, méplat</span> (recherche à l'éclairage jour frisant, bras pendants puis relevés)</li>\n                <li><span><span class=\"nc-red_bg\">Squirrhe mammaire</span></span> (<span class=\"nc-green_bg\">tumeur</span> dure avec épaississement ± bourgeonnement)</li>\n                <li><span><span class=\"nc-red_bg\">Ulcération cutanée</span></span>, <span><span class=\"nc-red_bg\">nodules de perméation</span></span></li>\n                <li><span class=\"nc-blue_bg\">Empâtement</span>, <span><span class=\"nc-red_bg\">lésion</span></span><span class=\"nc-red_bg\"> croûteuse</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span>Inflammation (<span class=\"nc-red nc-bold\">T4d</span>)</span></td>\n            <td>\n              Cancer <span>inflammatoire</span> défini par l'association de :\n              <ul>\n                <li><span>Placard</span> <span>érythémateux chaud</span> ± douloureux</li>\n                <li><span>Œdème</span> cutané avec aspect de <strong>« peau d'orange »</strong></li>\n                <li>Présence de ces signes sur <span><span class=\"nc-red nc-bold\">≥ 1/3 du sein</span></span></li>\n                <li><span>Évolution</span> <strong>rapide en quelques semaines</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td>Adhérence</td>\n            <td>\n              <ul>\n                <li><strong>Pincement de la peau</strong> en regard de la tumeur : mobilité / peau</li>\n                <li><strong><span><span class=\"nc-blue_bg\">Manœuvre de Tillaux</span></span></strong><span class=\"nc-blue_bg\"> (adduction contrariée du bras)</span> : mobilité / muscle grand pectoral</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span>Adénopathies</span></td>\n            <td>\n              <ul>\n                <li><span>Axillaires ± sus-claviculaires</span> : augmentées de volume, dures</li>\n                <li>Aires <strong>mammaires internes</strong> : non accessibles à l'examen clinique</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td>Métastases révélatrices</td>\n            <td><span>AEG</span>, <span>douleurs osseuses</span>, <span>dyspnée</span>, <span>toux</span>, <span>nausées</span>, <span>céphalées</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewbox=\"0 0 560 208\" role=\"img\" aria-label=\"Schéma de convergence : les quatre critères placard érythémateux chaud, œdème en peau d&#x27;orange, signes sur au moins un tiers du sein et évolution rapide en quelques semaines définissent par leur association le cancer du sein inflammatoire de stade T4d.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"15\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">Cancer du sein <span>inflammatoire</span> (T4d) — 4 critères associés</text>\n          <rect class=\"fb-amber\" x=\"12\" y=\"28\" width=\"224\" height=\"38\" rx=\"6\"></rect>\n          <text class=\"tx-amber\" x=\"124\" y=\"51\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"600\"><span>Placard</span> érythémateux chaud</text>\n          <rect class=\"fb-amber\" x=\"12\" y=\"72\" width=\"224\" height=\"38\" rx=\"6\"></rect>\n          <text class=\"tx-amber\" x=\"124\" y=\"95\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"600\"><span>Œdème</span> « peau d'orange »</text>\n          <rect class=\"fb-amber\" x=\"12\" y=\"116\" width=\"224\" height=\"38\" rx=\"6\"></rect>\n          <text class=\"tx-amber\" x=\"124\" y=\"139\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"600\">Signes sur <span>≥ 1</span>/3 du sein</text>\n          <rect class=\"fb-amber\" x=\"12\" y=\"160\" width=\"224\" height=\"38\" rx=\"6\"></rect>\n          <text class=\"tx-amber\" x=\"124\" y=\"183\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"600\"><span>Évolution</span> rapide (qq semaines)</text>\n          <rect class=\"fb-red\" x=\"320\" y=\"78\" width=\"228\" height=\"72\" rx=\"8\"></rect>\n          <text class=\"tx-red\" x=\"434\" y=\"110\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">Cancer du sein</text>\n          <text class=\"tx-red\" x=\"434\" y=\"128\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">inflammatoire (T4d)</text>\n          <line class=\"ln\" x1=\"236\" y1=\"47\" x2=\"314\" y2=\"92\" stroke-width=\"1.5\"></line>\n          <polygon class=\"ah\" points=\"320,92 312,88 312,96\"></polygon>\n          <line class=\"ln\" x1=\"236\" y1=\"91\" x2=\"314\" y2=\"106\" stroke-width=\"1.5\"></line>\n          <polygon class=\"ah\" points=\"320,106 312,102 312,110\"></polygon>\n          <line class=\"ln\" x1=\"236\" y1=\"135\" x2=\"314\" y2=\"120\" stroke-width=\"1.5\"></line>\n          <polygon class=\"ah\" points=\"320,120 312,116 312,124\"></polygon>\n          <line class=\"ln\" x1=\"236\" y1=\"179\" x2=\"314\" y2=\"134\" stroke-width=\"1.5\"></line>\n          <polygon class=\"ah\" points=\"320,134 312,130 312,138\"></polygon>\n        </svg>\n        <figcaption>Le cancer du sein inflammatoire (T4d) se définit par l'<strong>association</strong> des 4 critères — mastectomie + curage + <span>chimiothérapie</span> néoadjuvante, quel que soit le sous-type.</figcaption>\n      </figure>\n\n      <div class=\"callout callout-danger\"><strong><span>Drapeau <span class=\"nc-red nc-bold\">rouge</span></span>.</strong> L'association <span>érythème chaud + œdème en peau d'orange + évolution rapide en quelques semaines + atteinte de <span class=\"nc-red nc-bold\">≥ 1/3 du sein</span></span> définit le <span><span class=\"nc-red nc-bold\">cancer du sein inflammatoire</span> (<span class=\"nc-red nc-bold\">T4d</span>)</span>. <span><span class=\"nc-pink_bg\">Mastectomie totale</span></span> + <span>curage axillaire</span> + <span><span class=\"nc-pink\">chimiothérapie néoadjuvante</span></span> systématique, quel que soit le sous-type moléculaire.</div>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> L'<span>eczéma</span> du mamelon n'est <span>jamais banal</span> : un aspect eczématiforme persistant et <span class=\"nc-red nc-bold\">unilatéral</span> de la <span>plaque</span> aréolo-mamelonnaire évoque une <span><span class=\"nc-orange nc-bold\">maladie de Paget</span></span> du <span class=\"nc-orange nc-bold\">sein</span> → <span><span class=\"nc-blue nc-bold\">punch</span>-biopsie <span class=\"nc-red_bg nc-bold\">cutanée</span></span> systématique.</div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li></ul></details>","frequence":4},{"id":"312-7","rang":"B","rubrique":"Contenu multimédia","titre":"Photographies de lésions/anomalies cutanées sein","contenu":"<div class=\"notion-course\"><p>Cet objectif est un objectif de <span>reconnaissance visuelle</span> : à l'EDN, les <span>vignettes</span> peuvent présenter une photographie clinique du sein et demander d'identifier le <span>signe cutané</span> et le diagnostic évoqué. La sémiologie textuelle à connaître recouvre les principales présentations visibles à l'<span>inspection</span>.</p>\n      <h4>Cinq signes cutanés à reconnaître</h4>\n      <table>\n        <thead>\n          <tr><th>Signe</th><th>Description</th><th>Diagnostic évoqué</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span><span class=\"nc-orange nc-bold\">Maladie de Paget</span></span> du mamelon</td>\n            <td><span class=\"nc-blue_bg\">Aspect </span><strong><span class=\"nc-blue_bg\">eczématiforme</span></strong><span class=\"nc-blue_bg\"> du mamelon</span> et de l'aréole : <span>érythème, érosion, croûtes, prurit</span>, unilatéral et persistant malgré les soins locaux</td>\n            <td><span>Carcinome canalaire associé</span> (in situ ou invasif) → <span>punch-biopsie <span class=\"nc-red_bg nc-bold\">cutanée</span></span></td>\n          </tr>\n          <tr>\n            <td><span>Peau d'orange</span></td>\n            <td><span>Œdème cutané dermique</span> donnant un aspect d'orifices pilo-sébacés saillants — souvent associé à <span>érythème et chaleur</span></td>\n            <td><span><span class=\"nc-red_bg\">Cancer du sein</span> inflammatoire (<span class=\"nc-red nc-bold\">T4d</span>)</span></td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-blue_bg\">Rétraction cutanée</span></span></td>\n            <td><span>Fossette ou méplat localisé</span> en regard d'une tumeur sous-jacente — visible à l'inspection bras relevés, parfois uniquement à l'éclairage frisant</td>\n            <td><span>Cancer <span class=\"nc-red nc-bold\">infiltrant</span></span> avec <span>adhérence <span class=\"nc-red_bg nc-bold\">cutanée</span></span></td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-red_bg\">Ulcération cutanée</span></span></td>\n            <td><span>Perte de substance bourgeonnante ou nécrotique</span>, parfois associée à des <span><span class=\"nc-red_bg\">nodules de perméation</span></span></td>\n            <td>Cancer évolué (souvent <span>T4b</span>) découvert tardivement</td>\n          </tr>\n          <tr>\n            <td><span>Écoulement sanglant</span></td>\n            <td><span>Goutte de sang spontanée, unilatérale, <span class=\"nc-red nc-bold\">unipore</span></span> — visible à l'inspection ou provoquée par pression douce</td>\n            <td><span>Cancer canalaire</span> ou <span>papillome intra-canalaire</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">Photographies cliniques disponibles dans les illustrations de cet objectif : rétraction et anomalie <span class=\"nc-red_bg nc-bold\">inflammatoire</span>. Elles complètent l’examen clinique et ne remplacent pas la confirmation diagnostique.</div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li></ul></details>","frequence":0},{"id":"312-8","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications de la mammographie","contenu":"<div class=\"notion-course\"><p>La <span><span class=\"nc-blue_bg\">mammographie</span></span> est l'<span class=\"nc-yellow_bg\">examen de </span><strong><span class=\"nc-yellow_bg\">1</span><sup><span class=\"nc-yellow_bg\">ère</span></sup><span class=\"nc-yellow_bg\"> intention</span></strong><span class=\"nc-yellow_bg\"> devant toute anomalie mammaire</span> ou dans le cadre du <span>dépistage</span>. Elle est <span>contre-indiquée</span> chez la femme très jeune (<span><span class=\"nc-pink nc-bold\">&lt; 30 ans</span></span>) et chez la <span>femme enceinte</span> (<span class=\"nc-green\">seins denses</span> non lisibles) — on lui substitue l'<span><span class=\"nc-blue_bg\">échographie</span></span>.</p>\n      <h4>Modalités techniques</h4>\n      <table>\n        <thead>\n          <tr><th>Paramètre</th><th>Modalité</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Réalisation</strong></td><td>Radiologue agréé formé (<span>≥ 500 mammographies/an</span>)</td></tr>\n          <tr><td><strong>2 incidences systématiques</strong></td><td><span class=\"nc-blue nc-bold\">Oblique externe</span> + cranio-caudale</td></tr>\n          <tr><td><strong>Période optimale</strong> (femme non ménopausée)</td><td><span>1<sup>ère</sup> partie de cycle</span> (seins moins denses et moins douloureux)</td></tr>\n          <tr><td><strong>Comparaison</strong></td><td>Bilatérale + avec les clichés antérieurs si disponibles</td></tr>\n          <tr><td><strong>Compléments possibles</strong></td><td><span>Tomosynthèse 3D</span>, clichés profil ou agrandis, compression localisée</td></tr>\n        </tbody>\n      </table>\n      <h4>Indications</h4>\n      <table>\n        <thead>\n          <tr><th>Contexte</th><th>Indication</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Dépistage</span> organisé</strong></td>\n            <td>Femmes <span>50-74 ans</span> tous les <span><span class=\"nc-pink nc-bold\">2 ans</span></span>, <span class=\"nc-green nc-bold\">sans signes cliniques</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Dépistage</span> individuel</strong></td>\n            <td>Femmes à haut risque (ATCD personnels, familiaux, <span>irradiation</span> thoracique, <span>lésion</span> à risque) : <span><span class=\"nc-blue_bg\">mammographie</span></span> <span class=\"nc-pink nc-bold\">annuelle</span></td>\n          </tr>\n          <tr>\n            <td><strong>Démarche diagnostique</strong></td>\n            <td><span class=\"nc-yellow_bg\">Toute anomalie clinique mammaire</span> (<span>nodule</span>, <span>écoulement suspect</span>, <span>rétraction</span>, modification <span class=\"nc-red_bg nc-bold\">cutanée</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span>Bilan préthérapeutique</span></strong></td>\n            <td><span class=\"nc-blue_bg\">Mammographie bilatérale</span> systématique avant traitement d'un <span class=\"nc-red_bg\">cancer du sein</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>Surveillance</span> post-traitement</strong></td>\n            <td>1 fois/an à vie ou jusqu'à la 10<sup>e</sup> année (sauf si <span class=\"nc-pink_bg\">mastectomie totale</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Sémiologie : <span>lésion</span> suspecte <span>vs</span> bénigne</h4>\n      <table>\n        <thead>\n          <tr><th>Critère</th><th><span>Nodule</span> malin</th><th>Nodule bénin</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Limites / contours</td><td><span>Mal limité, irrégulier, spiculé</span>, rétractile</td><td>Limites nettes</td></tr>\n          <tr><td>Densité</td><td>Hétérogène, <span class=\"nc-blue_bg\">centre dense</span>, halo clair œdémateux</td><td>Homogène</td></tr>\n          <tr><td>Architecture</td><td><span><span class=\"nc-red nc-bold\">Rupture architecturale</span></span></td><td>Respectée</td></tr>\n          <tr><td>Calcifications</td><td><span>Microcalcifications</span> vermiculaires, arborescentes, irrégulières, groupées, <span class=\"nc-blue_bg\">topographie galactophorique</span></td><td><span>Macrocalcifications</span></td></tr>\n          <tr><td>Échogénicité</td><td><span>Hypoéchogène</span></td><td><span>Anéchogène</span> (kyste)</td></tr>\n          <tr><td><span class=\"nc-green_bg\">Grand axe</span></td><td><span>Perpendiculaire à la peau</span> (= vertical)</td><td><span><span class=\"nc-green_bg\">Parallèle</span> à la peau</span> (dans le sens des canaux galactophoriques)</td></tr>\n          <tr><td>Postérieur (écho)</td><td><span>Cône d'ombre postérieur</span></td><td><span><span class=\"nc-green_bg\">Renforcement postérieur</span></span></td></tr>\n        </tbody>\n      </table>\n      <h4><span>Classification</span> BI-RADS (<span>ACR</span>)</h4>\n      <table>\n        <thead>\n          <tr><th>Classe ACR</th><th>Signification</th><th>Conduite à tenir</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span>ACR 0</span></strong></td><td>Examen incomplet</td><td>Complément à demander</td></tr>\n          <tr><td><strong><span>ACR 1</span></strong></td><td>Examen normal</td><td>Aucune action</td></tr>\n          <tr><td><strong><span>ACR 2</span></strong></td><td>Anomalie bénigne</td><td>Pas de <span>surveillance</span> particulière</td></tr>\n          <tr><td><strong><span>ACR 3</span></strong></td><td>Anomalie probablement bénigne</td><td><span>Surveillance à 6 mois</span></td></tr>\n          <tr><td><strong><span>ACR 4</span></strong></td><td>Anomalie suspecte</td><td><span>Biopsie indispensable</span></td></tr>\n          <tr><td><strong><span>ACR 5</span></strong></td><td>Anomalie évocatrice de malignité</td><td><span>Biopsie indispensable</span></td></tr>\n          <tr><td><strong><span>ACR 6</span></strong></td><td>Cancer prouvé histologiquement</td><td>—</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <svg viewbox=\"0 0 760 150\" role=\"img\" aria-labelledby=\"t312o7 d312o7\" preserveaspectratio=\"xMidYMid meet\" style=\"display:block;width:100%;max-width:720px;height:auto;margin:0 auto\">\n          <title id=\"t312o7\">Échelle BI-RADS (<span>ACR</span>) et conduite à tenir</title>\n          <desc id=\"d312o7\"><span>Classification</span> ACR de 0 à 6 par risque croissant de malignité ; le seuil décisif se situe entre ACR 3 (<span>surveillance</span>) et ACR 4 (<span>biopsie</span> obligatoire).</desc>\n          <text x=\"215\" y=\"28\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10\">ACR 0–3 : pas de biopsie</text>\n          <text x=\"585\" y=\"28\" text-anchor=\"middle\" fill=\"var(--spe-infectio)\" font-size=\"10\" font-weight=\"700\">ACR 4–6 : biopsie</text>\n          <line x1=\"431\" y1=\"36\" x2=\"431\" y2=\"132\" stroke=\"var(--spe-infectio)\" stroke-width=\"1.5\" stroke-dasharray=\"5 4\"></line>\n          <rect x=\"26\" y=\"42\" width=\"96\" height=\"46\" rx=\"8\" fill=\"var(--ink-muted)\"></rect>\n          <text x=\"74\" y=\"72\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"15\" font-weight=\"700\">ACR 0</text>\n          <text x=\"74\" y=\"108\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\">Incomplet</text>\n          <text x=\"74\" y=\"126\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\" font-weight=\"600\">Complément</text>\n          <rect x=\"128\" y=\"42\" width=\"96\" height=\"46\" rx=\"8\" fill=\"var(--spe-pneumo)\"></rect>\n          <text x=\"176\" y=\"72\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"15\" font-weight=\"700\">ACR 1</text>\n          <text x=\"176\" y=\"108\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\">Normal</text>\n          <text x=\"176\" y=\"126\" text-anchor=\"middle\" fill=\"var(--spe-pneumo)\" font-size=\"10.5\" font-weight=\"600\">Rien</text>\n          <rect x=\"230\" y=\"42\" width=\"96\" height=\"46\" rx=\"8\" fill=\"var(--spe-pneumo)\"></rect>\n          <text x=\"278\" y=\"72\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"15\" font-weight=\"700\">ACR 2</text>\n          <text x=\"278\" y=\"108\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\">Bénin</text>\n          <text x=\"278\" y=\"126\" text-anchor=\"middle\" fill=\"var(--spe-pneumo)\" font-size=\"10.5\" font-weight=\"600\">Rien</text>\n          <rect x=\"332\" y=\"42\" width=\"96\" height=\"46\" rx=\"8\" fill=\"var(--spe-orl)\"></rect>\n          <text x=\"380\" y=\"72\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"15\" font-weight=\"700\">ACR 3</text>\n          <text x=\"380\" y=\"108\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\">Proba. bénin</text>\n          <text x=\"380\" y=\"126\" text-anchor=\"middle\" fill=\"var(--spe-orl)\" font-size=\"10.5\" font-weight=\"600\">Surv.<span> 6 mois</span></text>\n          <rect x=\"434\" y=\"42\" width=\"96\" height=\"46\" rx=\"8\" fill=\"var(--spe-infectio)\"></rect>\n          <text x=\"482\" y=\"72\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"15\" font-weight=\"700\">ACR 4</text>\n          <text x=\"482\" y=\"108\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\">Suspect</text>\n          <text x=\"482\" y=\"126\" text-anchor=\"middle\" fill=\"var(--spe-infectio)\" font-size=\"10.5\" font-weight=\"600\">Biopsie</text>\n          <rect x=\"536\" y=\"42\" width=\"96\" height=\"46\" rx=\"8\" fill=\"var(--spe-infectio)\"></rect>\n          <text x=\"584\" y=\"72\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"15\" font-weight=\"700\">ACR 5</text>\n          <text x=\"584\" y=\"108\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\">Malignité</text>\n          <text x=\"584\" y=\"126\" text-anchor=\"middle\" fill=\"var(--spe-infectio)\" font-size=\"10.5\" font-weight=\"600\">Biopsie</text>\n          <rect x=\"638\" y=\"42\" width=\"96\" height=\"46\" rx=\"8\" fill=\"var(--spe-neuro)\"></rect>\n          <text x=\"686\" y=\"72\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"15\" font-weight=\"700\">ACR 6</text>\n          <text x=\"686\" y=\"108\" text-anchor=\"middle\" fill=\"var(--ink-muted)\" font-size=\"10.5\">Cancer prouvé</text>\n          <text x=\"686\" y=\"126\" text-anchor=\"middle\" fill=\"var(--spe-neuro)\" font-size=\"10.5\" font-weight=\"600\">PEC onco</text>\n        </svg>\n        <figcaption>Seuil décisif <strong>ACR 3 → 4</strong> : ACR <span>≤ 3</span> se surveille, ACR ≥ 4 impose une <strong>biopsie</strong> histologique.</figcaption>\n      </figure>\n      <h4><span>Échographie</span> axillaire — au même titre que la mammo-écho mammaire</h4>\n      <p>Indiquée devant <strong><span class=\"nc-yellow_bg\">toute anomalie clinique mammaire</span></strong>. Recherche d'<span>adénopathie axillaire suspecte</span>.</p>\n      <table>\n        <thead>\n          <tr><th>Signe suspect (cytoponction justifiée si <span>≥ 1</span>)</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-red_bg\">Épaississement cortical</span></span><span class=\"nc-red_bg\"> focal ou global</span></td></tr>\n          <tr><td><span><span class=\"nc-red_bg\">Absence de hile graisseux et vasculaire</span></span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> L'<span><span class=\"nc-blue_bg\">échographie</span></span> est systématiquement <span>associée à la <span class=\"nc-blue_bg\">mammographie</span></span> chez la femme jeune et chez les patientes à densité mammaire élevée (type C/D <span>ACR</span>). Chez la femme enceinte ou de <span><span class=\"nc-pink nc-bold\">&lt; 30 ans</span></span>, l'<span><span class=\"nc-blue_bg\">échographie</span></span> remplace la <span><span class=\"nc-blue_bg\">mammographie</span></span> en 1<sup>ère</sup> intention.</div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li></ul></details>","frequence":3},{"id":"312-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications de la biopsie mammaire","contenu":"<div class=\"notion-course\"><ul><li>Les lésions ACR/BI-RADS 4 ou 5 nécessitent une preuve histologique, habituellement par prélèvement percutané guidé. ACR 0 impose un complément d’imagerie ; ACR 3 une surveillance rapprochée dans une situation concordante.</li><li>Microbiopsie surtout pour une masse repérée à l’échographie ; macrobiopsie notamment pour microcalcifications ou certaines lésions non massiques, guidée par la technique qui montre la lésion.</li><li>La cytoponction seule ne fournit pas les mêmes informations architecturales qu’une biopsie. L’histologie précise type, grade et biomarqueurs nécessaires au traitement.</li><li>Toujours confronter clinique, imagerie et histologie. Une lésion cliniquement suspecte ou une discordance ne doit pas être classée rassurante sur un résultat d’imagerie/biopsie isolé.</li><li>Si résultat bénin concordant : suivi adapté ; si prélèvement insuffisant ou discordant : nouvelle investigation/prélèvement. La catégorie ACR n’est pas à elle seule un diagnostic histologique.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li></ul></details>","frequence":3},{"id":"312-10","rang":"B","rubrique":"Définition","titre":"Connaître les principaux types de lésions bénignes et de tumeurs malignes du sein","contenu":"<div class=\"notion-course\"><p>Trois grandes catégories d'entités à distinguer : <strong>lésions bénignes simples</strong> (pas de risque de cancer), <strong>lésions bénignes à risque</strong> (<span>chirurgie</span> souvent indiquée) et <strong>tumeurs malignes</strong> (<span>in situ</span> <span>vs</span> <span>invasif</span>).</p>\n      <h4>Lésions bénignes simples — pas de sur-risque de cancer</h4>\n      <table>\n        <thead>\n          <tr><th>Entité</th><th>Caractéristiques cliniques</th><th>Risque / PEC</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span><span class=\"nc-orange_bg\">Adénofibrome</span></span> (fibroadénome)</td>\n            <td><span class=\"nc-green_bg\">Tumeur</span> la plus fréquente de la <span>femme <span class=\"nc-pink nc-bold\">&lt; 30 ans</span></span>. <span>Prolifération mixte épithéliale et conjonctive</span>. <span>Nodule unique ou multiple, <span class=\"nc-green\">indolore</span>, bien limité, <span class=\"nc-green\">mobile</span>, <span class=\"nc-green\">ferme</span> « caoutchouteux »</span>, <span><span class=\"nc-pink\">&lt; 3 cm</span></span>. Écho : <span>masse</span> <span><span class=\"nc-blue nc-bold\">hypoéchogène</span></span>, ovale, bords réguliers, <span class=\"nc-blue_bg\">grand axe parallèle à la peau</span>, <span><span class=\"nc-green_bg\">macrocalcifications</span></span> possibles.</td>\n            <td>Pas de sur-risque. <span>Surveillance <span class=\"nc-pink nc-bold\">annuelle</span> clinique</span> ± écho. <span>Microbiopsie</span> si <span><span class=\"nc-pink\">&gt; 30 ans</span></span>, imagerie atypique, croissance rapide. <span>Chirurgie</span> si gêne, <span class=\"nc-blue\">douleur</span>, <span>lésion</span> volumineuse, ou après <span>35 ans</span>.</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-orange_bg\">Mastopathie fibrokystique</span> (MFK)</span></td>\n            <td>Maladie bénigne la plus fréquente entre <span><span class=\"nc-pink nc-bold\">35-50 ans</span></span>. <span>Mastodynies cycliques</span> pré-menstruelles, <span>placards granuleux sensibles</span>, <span>kystes mammaires</span>, <span>écoulement jaune/verdâtre/blanchâtre</span>. <span>Échographie</span> : Kystes <span class=\"nc-green_bg\">simples : </span><span><span class=\"nc-green_bg\">masse</span></span> <span><span class=\"nc-green_bg\">anéchogène</span></span> <span class=\"nc-green\">arrondie</span> bien limitée <span>avec <span class=\"nc-green_bg\">renforcement postérieur</span></span>. <span class=\"nc-yellow_bg\">Kystes atypiques</span> : parois <span class=\"nc-red_bg\">épaisses</span> <span class=\"nc-red_bg\">irrégulières</span>, <span class=\"nc-red_bg\">végétations</span> <span class=\"nc-red_bg\">intrakystiques</span>.</td>\n            <td>Pas de sur-<span class=\"nc-green_bg nc-bold\">risque</span> (sauf <span class=\"nc-orange_bg\">hyperplasie atypique</span> associée). PEC : <span>règles hygiéno-diététiques</span> (soutien-gorge, ↓ tabac/café/<span class=\"nc-yellow_bg\">alcool</span>), <span><span class=\"nc-pink\">progestatifs</span></span> en 2<sup>e</sup> partie de cycle. <span>Chirurgie</span> rare (<span class=\"nc-red\">kyste atypique</span>, récidive après ponctions itératives).</td>\n          </tr>\n          <tr>\n            <td><span>Hamartome</span></td>\n            <td><span>Lésion</span> rare, tissu glandulaire + fibreux + adipeux mêlés</td>\n            <td>Pas de <span>chirurgie</span> ni de <span>surveillance</span> spécifique</td>\n          </tr>\n          <tr>\n            <td><span>Cytostéatonécrose</span></td>\n            <td>Autodigestion du tissu adipeux par les lipases adipocytaires. Souvent <span>post-traumatisme</span>, <span>post-chirurgie ou post-radiothérapie</span>. Aspect parfois inquiétant (<span class=\"nc-blue_bg\">rétraction cutanée</span>, densification, inflammation)</td>\n            <td>Imagerie redresse le diagnostic. Régression spontanée dans <span>90 %</span> des cas. <span>Surveillance</span> simple, pas de <span>chirurgie</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Lésions bénignes à risque de cancer — <span>chirurgie</span> souvent indiquée</h4>\n      <table>\n        <thead>\n          <tr><th>Entité</th><th>Caractéristiques</th><th>PEC</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span><span class=\"nc-orange_bg\">Hyperplasie canalaire atypique</span></span></td>\n            <td>RR <span>×4-5</span>. Souvent découverte sur microbiopsie pour <span>microcalcifications</span></td>\n            <td><span>Exérèse chirurgicale</span> recommandée (risque de sous-estimation d'une <span>lésion</span> cancéreuse sous-jacente)</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-orange_bg\">Hyperplasie lobulaire atypique</span> / <span class=\"nc-red_bg\">Carcinome lobulaire in situ</span> (CLIS)</span></td>\n            <td><span>Pas un pré-cancer canalaire direct</span> mais <span>marqueur de risque bilatéral diffus</span>. Classé dans les <strong>lésions bénignes à risque</strong> (à la différence du CCIS)</td>\n            <td><span>Exérèse</span> + <span>surveillance</span> rapprochée bilatérale</td>\n          </tr>\n          <tr>\n            <td><span>Papillome intra-canalaire</span></td>\n            <td>Prolifération épithéliale intra-canaliculaire. <span>Écoulement mamelonnaire parfois sanglant</span></td>\n            <td><span>Exérèse <span class=\"nc-pink\">chirurgicale</span></span> (sauf petite <span>lésion</span> totalement disparue après <span>macrobiopsie</span>)</td>\n          </tr>\n          <tr>\n            <td><span>Tumeur phyllode</span></td>\n            <td>Double composante fibro-épithéliale. <strong>Principal <span>diagnostic différentiel</span> de l'adénofibrome</strong>. Bénin à malin selon le <span>grade</span></td>\n            <td><span>Exérèse chirurgicale</span> recommandée</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Tumeurs malignes — typologie</h4>\n      <table>\n        <thead>\n          <tr><th>Type</th><th>Fréquence</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-red_bg\">Carcinome</span></span><span class=\"nc-red_bg\"> canalaire in situ</span> (CCIS)</strong></td>\n            <td>Non <span class=\"nc-red nc-bold\">infiltrant</span></td>\n            <td><span>Vrai pré-cancer</span>. Pas de <span class=\"nc-red nc-bold\">franchissement de la </span><span><span class=\"nc-red nc-bold\">membrane basale</span></span>, <span>risque métastatique nul</span>. <span><span class=\"nc-green_bg\">Évolution</span></span> possible en plusieurs années vers un cancer invasif. PEC : <span><span class=\"nc-pink nc-bold\">chirurgie</span></span><span class=\"nc-pink nc-bold\"> systématique</span> avec marge <span>≥ <span class=\"nc-pink nc-bold\">2 mm</span></span>, pas de traitement systémique.</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-yellow_bg\">Carcinome</span></span><span class=\"nc-yellow_bg\"> canalaire infiltrant</span></strong> (= <span class=\"nc-yellow_bg\">carcinome infiltrant non spécifique</span>)</td>\n            <td><span>~90 %</span></td>\n            <td>Forme la plus fréquente</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-orange_bg\">Carcinome</span></span><span class=\"nc-orange_bg\"> lobulaire infiltrant</span></strong></td>\n            <td><span>~10 %</span></td>\n            <td>Souvent <span>multifocal</span> ou <span>bilatéral</span>. Cellules infiltrant « en file indienne » (perte de l'<span>E-cadhérine</span>). Dissémination volontiers péritonéale.</td>\n          </tr>\n          <tr>\n            <td><strong>Formes rares</strong></td>\n            <td>—</td>\n            <td><span>Carcinome médullaire</span> (à évoquer pour BRCA), mucineux, tubuleux, papillaire, lymphomes, sarcomes, métastases intra-mammaires</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Sous-types moléculaires (sur tout cancer <span class=\"nc-red nc-bold\">infiltrant</span>)</h4>\n      <table>\n        <thead>\n          <tr><th>Sous-type</th><th>RH</th><th>HER2</th><th>Ki67</th><th>Traitement principal</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Luminal A</td><td><span>RO</span>+ / <span>RP</span> <span>≥ 20 %</span></td><td>Négatif</td><td><span>&lt; 20 %</span></td><td><span>Hormonothérapie</span></td></tr>\n          <tr><td>Luminal B</td><td>RO+ / <span>RP</span> &lt;<span> 20 %</span></td><td>Négatif</td><td><span>≥ 20 %</span></td><td><span class=\"nc-pink_bg\">Hormonothérapie</span> + <span><span class=\"nc-pink nc-bold\">chimiothérapie</span></span></td></tr>\n          <tr><td>HER2+ (<span>15 %</span>)</td><td>+ ou −</td><td>Positif</td><td>Mauvais <span>pronostic</span></td><td><span><span class=\"nc-pink nc-bold\">Trastuzumab</span></span> + <span><span class=\"nc-pink nc-bold\">chimiothérapie</span></span> ± <span class=\"nc-pink_bg\">hormonothérapie</span> si RH+</td></tr>\n          <tr><td><span class=\"nc-red nc-bold\">Triple négatif</span> (<span>15 %</span>)</td><td>Négatifs</td><td><span class=\"nc-red nc-bold\">Négatif</span></td><td>Très mauvais <span>pronostic</span></td><td><span><span class=\"nc-pink nc-bold\">Chimiothérapie</span> systématique</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span>Drapeau <span class=\"nc-red nc-bold\">rouge</span></span>.</strong> Ne pas confondre <span>CCIS</span> (<span><span class=\"nc-red_bg\">carcinome</span></span><span class=\"nc-red_bg\"> </span><em><span class=\"nc-red_bg\">canalaire</span></em><span class=\"nc-red_bg\"> in situ</span> — vrai pré-cancer, <span><span class=\"nc-pink nc-bold\">chirurgie</span></span><span class=\"nc-pink nc-bold\"> systématique</span>) et <span>CLIS</span> (<span class=\"nc-red_bg\">carcinome </span><em><span class=\"nc-red_bg\">lobulaire</span></em><span class=\"nc-red_bg\"> in situ</span> — classé dans les lésions bénignes à <span class=\"nc-green_bg nc-bold\">risque</span>, marqueur de <span class=\"nc-green_bg nc-bold\">risque</span> bilatéral). Le CCIS impose un traitement local complet ; le CLIS impose une <span>surveillance</span> rapprochée <span class=\"nc-blue_bg\">bilatérale</span>.</div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li></ul></details>","frequence":2},{"id":"312-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principes du bilan d'extension d'un cancer du sein","contenu":"<div class=\"notion-course\"><p>Le <span><span class=\"nc-yellow_bg\">bilan d'extension</span></span> est indispensable avant le protocole thérapeutique du <span class=\"nc-red_bg\">cancer du sein</span> <strong><span class=\"nc-red nc-bold\">infiltrant</span></strong>. Il comprend un <strong>bilan loco-régional</strong> systématique, un <strong>bilan à distance</strong> ciblé selon le <span>stade</span> et un <strong><span>bilan préthérapeutique</span></strong> <span>biologique</span>. La <span>stadification</span> est résumée par le <span>TNM</span> (<span>cTNM</span> clinique, <span>pTNM</span> anatomopathologique, <span>ypTNM</span> après néoadjuvant).</p>\n      <h4>Bilan loco-régional (systématique)</h4>\n      <ul>\n        <li><span><span class=\"nc-blue_bg\">Mammographie bilatérale</span></span></li>\n        <li><span><span class=\"nc-blue_bg\">Échographie mammaire</span></span></li>\n        <li><span>Échographie axillaire</span> ± cytoponction d'<span>adénopathie</span> suspecte</li>\n      </ul>\n      <h4><span>IRM</span> mammaire — indications ciblées (rang C)</h4>\n      <table>\n        <thead>\n          <tr><th>Indication</th><th>Justification clinique</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-pink\">Oncoplastie majeure</span></span> (prothèse mammaire)</td><td>Mammographie/écho peu informatives</td></tr>\n          <tr><td>Femme <span>&lt; 40 ans</span></td><td><span class=\"nc-green\">Seins denses</span>, sensibilité mammo réduite</td></tr>\n          <tr><td><span class=\"nc-green\">Seins </span><span><span class=\"nc-green\">denses</span> ACR C/D</span> non évaluables</td><td>Densité masque les lésions en mammo</td></tr>\n          <tr><td><span>Carcinome lobulaire infiltrant</span></td><td>Volontiers <span>multifocal et bilatéral</span></td></tr>\n          <tr><td><span><span class=\"nc-orange\">Adénomégalie métastatique</span></span> sans anomalie mammo/écho</td><td>Recherche <span class=\"nc-green_bg\">tumeur</span> primitive mammaire occulte</td></tr>\n          <tr><td>Discordance radio-clinique sur la <span>taille tumorale</span></td><td>Préciser avant traitement conservateur</td></tr>\n          <tr><td>Avant <span><span class=\"nc-pink nc-bold\">chimiothérapie néoadjuvante</span></span></td><td>Bilan initial pour évaluation de la réponse</td></tr>\n          <tr><td>Recherche de tumeur primitive si imagerie <span class=\"nc-red nc-bold\">négative</span></td><td>Métastases révélatrices sans primitif évident</td></tr>\n        </tbody>\n      </table>\n      <h4>Bilan à distance — indications formelles (<span>carcinome</span> infiltrant)</h4>\n      <table>\n        <thead>\n          <tr><th>Situation</th><th>Bilan à distance</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Tumeurs <span>≥ 3 cm</span></td>\n            <td><span>Oui</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"nc-red_bg\">Tumeurs avec atteinte</span> <span><span class=\"nc-red_bg nc-bold\">cutanée</span></span>, <span><span class=\"nc-red_bg nc-bold\">musculaire</span></span> ou <span><span class=\"nc-red_bg nc-bold\">inflammatoire</span></span> (stades T4)</td>\n            <td>Oui</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-red_bg\">Envahissement</span></span><span class=\"nc-red_bg\"> ganglionnaire</span> <strong>N+</strong> (cytoponction ou post-<span>chirurgie</span>)</td>\n            <td>Oui</td>\n          </tr>\n          <tr>\n            <td><span class=\"nc-red_bg\">Signes d'appel cliniques de métastase</span></td>\n            <td>Oui</td>\n          </tr>\n          <tr>\n            <td>Tumeurs <strong>T2</strong> avec sous-type <span><span class=\"nc-red nc-bold\">triple négatif</span></span> ou <span>HER2+</span></td>\n            <td>Oui (selon collège de gynécologie)</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-orange_bg\">Carcinome in situ</span></span> (CCIS)</td>\n            <td><strong>Non</strong> — pas de risque de dissémination</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Options techniques (hiérarchie selon disponibilité)</h4>\n      <ul>\n        <li><span>TEP-TDM au 18-FDG</span> ± <span>CA 15-3</span> + <span>ACE</span> — <strong>option préférée si disponible</strong></li>\n        <li><span><span class=\"nc-yellow_bg\">TDM TAP injectée</span></span> + <span>scintigraphie osseuse</span> ± <span><span class=\"nc-pink_bg\">CA 15-3</span></span> + <span><span class=\"nc-pink_bg\">ACE</span></span> — alternative</li>\n        <li><span>RX thoracique</span> + <span>écho abdominale</span> + <span>scintigraphie osseuse</span> — <span>à défaut</span> uniquement</li>\n        <li><span>IRM corps entier</span> chez la <span>femme enceinte</span> (<span>irradiation</span> <span>à éviter</span>)</li>\n      </ul>\n      <h4><span>Bilan préthérapeutique</span> (biologie)</h4>\n      <p><span>NFS</span>, <span>hémostase</span>, <span>calcémie</span>, <span>bilan hépatique</span>. Le <span>CA 15-3</span> est <span>optionnel</span> (peu sensible, peu spécifique, souvent <span class=\"nc-red nc-bold\">négatif</span> au diagnostic) — utile principalement au <span>suivi</span> de la <span class=\"nc-red nc-bold\">maladie métastatique</span>.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Pas de <span><span class=\"nc-yellow_bg\">bilan d'extension</span></span> dans le <strong>CCIS</strong> (<span class=\"nc-green_bg nc-bold\">risque</span> métastatique nul). Pour le cancer <span class=\"nc-red nc-bold\">infiltrant</span>, l'indication formelle repose sur la taille, le T, le N et le sous-type moléculaire. Le <span>carcinome lobulaire</span> a un bilan adapté (<span>TDM</span>/<span>TEP</span> en raison du tropisme péritonéal).</div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li></ul></details>","frequence":1},{"id":"312-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les objectifs et principes de traitement du cancer du sein","contenu":"<div class=\"notion-course\"><p>Les traitements visent à <strong><span>exérèse</span> de la tumeur</strong>, <strong>traitement des éventuelles métastases</strong>, <strong><span>réduction</span> du <span class=\"nc-green_bg nc-bold\">risque</span> de <span class=\"nc-green nc-bold\">récidive</span></strong>, <strong>ralentissement de l'<span>évolution</span></strong> et <strong>amélioration de la qualité de vie</strong>. Toute décision est prise en <span>RCP</span> (<span>réunion de concertation pluridisciplinaire</span>) et formalisée dans un <span>programme personnalisé de soins (PPS)</span>. <span>PEC à 100 %</span> par la sécurité sociale.</p>\n      <h4><span>Chirurgie</span> mammaire</h4>\n      <table>\n        <thead>\n          <tr><th>Option</th><th>Principe</th><th>Indications</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Traitement conservateur</strong></td>\n            <td><span class=\"nc-pink_bg\">Tumorectomie</span> (palpable) ou zonectomie / <span class=\"nc-red_bg nc-bold\">mastectomie</span> partielle (non palpable) <strong>+ <span><span class=\"nc-yellow_bg\">radiothérapie mammaire</span></span><span class=\"nc-yellow_bg\"> systématique</span></strong></td>\n            <td><span class=\"nc-green_bg\">Tumeur</span> de petite taille par rapport au volume du sein, unique, accessible</td>\n          </tr>\n          <tr>\n            <td><strong>Traitement radical (<span class=\"nc-pink_bg\">mastectomie totale</span>)</strong></td>\n            <td>Ablation du <span class=\"nc-orange nc-bold\">sein</span>, du revêtement cutané et du mamelon</td>\n            <td>\n              <ul>\n                <li><span class=\"nc-red_bg\">Cancer du sein</span> <span>inflammatoire (<span class=\"nc-red nc-bold\">T4d</span>)</span></li>\n                <li>Lésions <span>multifocales</span> dans des quadrants différents</li>\n                <li>Tumeur <span><span class=\"nc-pink nc-bold\">&gt; 5 cm</span></span> par rapport au volume du sein</li>\n                <li>Insuffisamment réduit par traitement systémique <span class=\"nc-yellow_bg\">néoadjuvant</span></li>\n                <li><span>CI à la radiothérapie</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Reconstruction mammaire</strong></td>\n            <td>Immédiate (cas par cas) ou secondaire (<span><span class=\"nc-pink nc-bold\">≥ 12 mois</span></span> après fin de la <span>RT</span>)</td>\n            <td>Après <span class=\"nc-pink_bg\">mastectomie totale</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <h4><span>Chirurgie</span> axillaire</h4>\n      <ul>\n        <li><strong><span>Ganglion sentinelle</span> :</strong> <span>1<sup>er</sup> relais ganglionnaire</span> repéré par injection de <span><span class=\"nc-blue nc-bold\">gadolinium</span></span> et/ou colorant (<span><span class=\"nc-blue nc-bold\">bleu patenté</span></span>, <span><span class=\"nc-blue nc-bold\">vert</span> <span class=\"nc-blue nc-bold\">d'indocyanine</span></span>). Indication : <span class=\"nc-green_bg\">tumeur</span> <span><span class=\"nc-green_bg nc-bold\">cT1</span> à T3</span> + absence d'atteinte ganglionnaire prouvée en pré-opératoire. <span><span class=\"nc-green nc-bold\">Évite le curage axillaire</span></span> si négatif.</li>\n        <li><strong>Curage axillaire :</strong> indiqué si <span><span class=\"nc-red_bg\">GS métastatique</span></span>, <span class=\"nc-red_bg\">tumeur cT4</span>, ou N+ prouvé en cytologie. Complications : <span>lymphœdème</span> du membre supérieur, <span>troubles sensitifs</span>, <span><span class=\"nc-blue_bg\">lymphocèle</span></span>, <span><span class=\"nc-blue_bg\">hématome</span></span>, <span><span class=\"nc-orange_bg\">enraidissement de l'épaule</span></span>.</li>\n      </ul>\n      <h4><span>Radiothérapie</span></h4>\n      <ul>\n        <li><strong>Mammaire :</strong> systématique après traitement conservateur (<span>RT</span> externe + boost sur le lit opératoire)</li>\n        <li><strong>Pariétale :</strong> après <span class=\"nc-pink_bg\">mastectomie totale</span> si FDR de mauvais <span>pronostic</span> (T <span><span class=\"nc-pink nc-bold\">&gt; 5 cm</span></span>, pN+, âge <span><span class=\"nc-pink nc-bold\">&lt; 35 ans</span></span>, <span><span class=\"nc-yellow_bg\">grade</span></span><span class=\"nc-yellow_bg\"> 3</span>, emboles tumoraux)</li>\n        <li><strong>Ganglionnaire :</strong> systématique si <strong>N+</strong> axillaire</li>\n      </ul>\n      <h4><span><span class=\"nc-pink nc-bold\">Chimiothérapie</span></span></h4>\n      <p>Polychimiothérapie : <span>anthracyclines</span> + <span>cyclophosphamide</span> ± <span>taxanes</span> (<span>docétaxel</span>, <span>paclitaxel</span>). Indiquée pour ~<span>30 %</span> des cancers infiltrants.</p>\n      <ul>\n        <li><strong>Néoadjuvante</strong> (pré-opératoire) : <span class=\"nc-red_bg\">cancers inflammatoires</span>, tumeurs <span>&gt; 1 cm</span> <span class=\"nc-red nc-bold\">triple négatif</span> ou HER2+, <span><span class=\"nc-red_bg\">envahissement</span></span><span class=\"nc-red_bg\"> ganglionnaire</span> massif (<span><span class=\"nc-red nc-bold\">cN2/N3</span></span>), tumeurs limites pour conservation</li>\n        <li><strong>Adjuvante</strong> (post-opératoire) : si FDR de mauvais <span>pronostic</span> (âge <span><span class=\"nc-pink nc-bold\">&lt; 35 ans</span></span>, T <span>≥ 2 cm</span>, N+, <span><span class=\"nc-yellow_bg\">grade</span></span><span class=\"nc-yellow_bg\"> 3</span>, emboles, <span class=\"nc-yellow_bg\">Ki67 </span><span><span class=\"nc-yellow_bg\">&gt; 20 %</span></span>, <span>RH−</span>, <span>HER2+</span>, <span class=\"nc-blue_bg\">cancer </span><span><span class=\"nc-blue_bg\">inflammatoire</span></span>)</li>\n      </ul>\n      <h4>Thérapies ciblées</h4>\n      <ul>\n        <li><span>Trastuzumab</span> (anti-HER2) : si <span><span class=\"nc-green_bg\">HER2+++</span></span> ou <span class=\"nc-yellow_bg\">HER2++</span> avec <span>amplification FISH</span>. Durée <span>1 an</span> (18 perfusions). <span><span class=\"nc-red nc-bold\">Cardiotoxique</span></span> → <span>surveillance</span> de la <strong>FEVG</strong> (<span><span class=\"nc-blue nc-bold\">échographie</span></span> ou <span><span class=\"nc-blue nc-bold\">scintigraphie</span></span><span class=\"nc-blue nc-bold\"> cardiaque</span>).</li>\n        <li><span><span class=\"nc-pink nc-bold\">T-DM1</span></span> : trastuzumab couplé à l'<span>emtansine</span> (résidu <span>tumoral</span> après chimio néoadjuvante)</li>\n        <li><span>Anti-PARP</span> : cancers <span>BRCA-mutés</span> (germinale ou somatique)</li>\n      </ul>\n      <h4><span class=\"nc-pink_bg\">Hormonothérapie</span></h4>\n      <p>Indiquée si <span>RH+</span> (RO et/ou <span>RP</span> <span>≥ 10 %</span>). <span class=\"nc-yellow_bg\">Prescrite en situation </span><strong><span class=\"nc-yellow_bg\">adjuvante</span></strong> après les traitements initiaux. Durée minimale <span>5 ans</span>, parfois étendue à <span><span class=\"nc-pink nc-bold\">10 ans</span></span>.</p>\n      <table>\n        <thead>\n          <tr><th>Statut</th><th>Molécule</th><th>Effets secondaires spécifiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Avant ménopause</td>\n            <td><span>Tamoxifène</span> (<span>SERM</span>) ± <span>analogues LH-RH</span> si <span class=\"nc-pink nc-bold\">&lt;</span><span><span class=\"nc-pink nc-bold\"> 35 ans</span></span> + facteurs de gravité</td>\n            <td><span><span class=\"nc-red nc-bold\">MTEV</span></span>, <span><span class=\"nc-red nc-bold\">cancer de l'endomètre</span></span>, <span><span class=\"nc-blue_bg\">leucorrhées</span></span>, <span><span class=\"nc-orange_bg\">hypercalcémie</span></span>. <span>Protecteur osseux</span>.</td>\n          </tr>\n          <tr>\n            <td>Après ménopause</td>\n            <td><span>Inhibiteurs d'<span class=\"nc-pink nc-bold\">aromatase</span></span> (<span><span class=\"nc-pink nc-bold\">anastrozole</span>, <span class=\"nc-pink nc-bold\">létrozole</span>, <span class=\"nc-pink nc-bold\">exémestane</span></span>). Tamoxifène possible si CI aux IA.</td>\n            <td><span><span class=\"nc-blue_bg\">Arthralgies</span>, <span class=\"nc-blue_bg\">myalgies</span></span>, <span><span class=\"nc-orange_bg\">dyslipidémie</span></span>, <span class=\"nc-orange_bg\">troubles de l'humeur</span>, <span><span class=\"nc-red_bg\">accentuation de la déminéralisation osseuse</span></span>. <span>CI en monothérapie chez la non-ménopausée</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Précautions sous inhibiteurs d'aromatase : <span><span class=\"nc-blue_bg\">surveillance</span></span><span class=\"nc-blue_bg\"> de la </span><span><span class=\"nc-blue_bg\">densitométrie osseuse</span></span>, apport <span>calcium + vitamine D</span>, <span>bisphosphonates</span> si FDR de fracture.</p>\n      <h4>Décision selon le sous-type (résumé)</h4>\n      <table>\n        <thead>\n          <tr><th>Sous-type</th><th><span>Chirurgie</span></th><th><span>Chimiothérapie</span></th><th><span>Radiothérapie</span></th><th>Hormonothérapie</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Luminal A (cN−)</td><td>Selon volume + GS</td><td>Rare (stades T3/T4, N+)</td><td>Mammaire si conservateur</td><td><strong>Systématique</strong></td></tr>\n          <tr><td>Luminal B (cN−)</td><td>Selon volume + GS</td><td>Selon FDR de récidive</td><td>Mammaire si conservateur</td><td><strong>Systématique</strong></td></tr>\n          <tr><td><span class=\"nc-red nc-bold\">Triple négatif</span> (cN−)</td><td>Selon volume + GS</td><td><strong>Systématique</strong>, souvent néoadjuvante</td><td>Mammaire si conservateur</td><td>Non</td></tr>\n          <tr><td>HER2+ (cN−)</td><td>Selon volume + GS</td><td><strong>Systématique</strong> + <span>trastuzumab ± T-DM1</span></td><td>Mammaire si conservateur</td><td>Si RH+</td></tr>\n          <tr><td>N+ (cN+)</td><td>Selon volume + <strong>curage axillaire</strong></td><td><strong>Systématique</strong></td><td><strong>Locorégionale systématique</strong></td><td>Si RH+</td></tr>\n          <tr><td><span>Inflammatoire</span> (T4d)</td><td><strong><span class=\"nc-pink_bg\">Mastectomie totale</span> + curage</strong></td><td><strong>Systématique, néoadjuvante</strong> ± anti-HER2</td><td><strong>Locorégionale systématique</strong></td><td>Si RH+</td></tr>\n        </tbody>\n      </table>\n      <h4><span>Surveillance</span> après traitement</h4>\n      <ul>\n        <li><strong>Clinique :</strong> tous les <span><span class=\"nc-pink nc-bold\">3-6 mois</span></span> pendant <span>5 ans</span>, puis 1×/an à vie ou jusqu'à la 10<sup>e</sup> année</li>\n        <li><strong>Imagerie :</strong> <span><span class=\"nc-blue_bg\">mammographie</span></span><span class=\"nc-blue_bg\"> bilatérale</span> + écho mammaire 1×/an à vie ou jusqu'à<span> 10 ans</span> (sauf mastectomie)</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le <span>tamoxifène</span> est un <span>facteur de <span class=\"nc-green_bg nc-bold\">risque</span> majeur de <span class=\"nc-red nc-bold\">MTEV</span></span> (TVP / EP) et de <span><span class=\"nc-red nc-bold\">cancer de l'endomètre</span></span> — toute métrorragie sous tamoxifène impose une <span><span class=\"nc-blue nc-bold\">échographie</span></span> pelvienne et une consultation gynécologique. Le <span><span class=\"nc-pink nc-bold\">trastuzumab</span></span> est <span><span class=\"nc-red nc-bold\">cardiotoxique</span></span> → FEVG avant et pendant le traitement.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 294 — Traitement des cancers · 295 — Prise en charge d'un malade cancéreux · 322 — Décision thérapeutique personnalisée · 226 — Thrombose veineuse profonde - EP</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li></ul></details>","frequence":7}],"astuces":[],"strategie":{"principes":"<p>Une <span class=\"kw-ttt\">chimiothérapie</span> est recommandée pour près de <span class=\"kw-chiffre\">30 %</span> des cancers du sein invasifs. Indications (néoadjuvant / adjuvant) discutées en <span class=\"kw-def\">RCP</span>.</p><p><strong><span class=\"kw-ttt\">Chimiothérapie</span> — molécules</strong></p><ul><li>Polychimiothérapie : <span class=\"kw-ttt\">anthracycline</span> + <span class=\"kw-ttt\">cyclophosphamide</span> ± <span class=\"kw-ttt\">docétaxel / paclitaxel</span></li></ul><p><strong><span class=\"kw-ttt\">Chimiothérapie</span> néoadjuvante (pré-opératoire)</strong></p><ul><li><span class=\"kw-alerte\">Cancers inflammatoires</span></li><li>Tumeurs agressives <span class=\"kw-chiffre\">&gt; 1 cm</span> (<span class=\"kw-clinique\">triple négatif</span> ou <span class=\"kw-clinique\">HER2+</span>)</li><li><span class=\"kw-bio\">Envahissement</span> ganglionnaire important (<span class=\"kw-clinique\">cN2/N3</span>)</li><li>Volume <span class=\"kw-etio\">tumoral</span> limite pour un traitement conservateur (objectif : <span class=\"kw-def\">réduire la taille</span>)</li></ul><p><strong><span class=\"kw-ttt\">Chimiothérapie</span> adjuvante</strong></p><ul><li>FR de mauvais <span class=\"kw-def\">pronostic</span> : âge <span class=\"kw-chiffre\">&lt; 35 ans</span> ; tumeur <span class=\"kw-chiffre\">≥ 2 cm</span> (≥ T2) ; cancer <span class=\"kw-etio\">inflammatoire</span> ; <span class=\"kw-clinique\">N+</span> (FR principal) ; <span class=\"kw-def\">grade</span> 3 ; emboles ; résidu post-néoadjuvant ; Ki67 <span class=\"kw-chiffre\">&gt; 20 %</span> ; <span class=\"kw-clinique\">RH−</span> ; <span class=\"kw-clinique\">HER2+</span></li><li>Discutée selon les <span class=\"kw-def\">signatures transcriptomiques</span> (OncotypeDX®, Prosigna®, Mammaprint® — rang C)</li></ul><p><strong>Thérapie ciblée anti-HER2 — trastuzumab</strong></p><ul><li>AC monoclonal inhibant la prolifération des cellules surexprimant <span class=\"kw-clinique\">HER2</span></li><li>Indication : tumeur <span class=\"kw-clinique\">HER2+</span> (3+ ou 2+ avec amplification en hybridation in situ), <span class=\"kw-def\">toujours associé à la chimiothérapie</span></li><li>Durée <span class=\"kw-chiffre\">1 an</span> (18 perfusions) ; renforcement par <span class=\"kw-ttt\">T-DM1</span> si résidu <span class=\"kw-etio\">tumoral</span> après néoadjuvant</li><li><span class=\"kw-alerte\">Cardiotoxique</span> → <span class=\"kw-def\">surveillance</span> de la <span class=\"kw-bio\">FEVG</span> (<span class=\"kw-imagerie\">échographie</span> ou <span class=\"kw-imagerie\">scintigraphie</span> cardiaque)</li></ul><p><strong>Hormonothérapie — si RH+ (RO et/ou <span class=\"kw-imagerie\">RP</span> <span class=\"kw-chiffre\">≥ 10 %</span>)</strong></p><p><span class=\"kw-ci\">Anti-aromatases CI en monothérapie chez la femme non ménopausée</span> + accélèrent la perte osseuse → <span class=\"kw-def\">surveillance</span> DMO, calcium/vit. D ± biphosphonate</p><ul><li>En situation <span class=\"kw-ttt\">adjuvante</span>, à la fin des traitements initiaux ; durée minimale <span class=\"kw-chiffre\">5 ans</span> (jusqu’à <span class=\"kw-chiffre\">10 ans</span> si haut risque de récidive)</li><li><span class=\"kw-def\">Avant la ménopause</span> : <span class=\"kw-ttt\">tamoxifène</span> (SERM) ± analogues de la LH-RH (suppression ovarienne si &lt;<span class=\"kw-chiffre\"> 35 ans</span> + facteurs de gravité)</li><li><span class=\"kw-def\">Après la ménopause</span> : <span class=\"kw-ttt\">anti-aromatases</span> (anastrozole, létrozole, exémestane) ; tamoxifène possible si CI</li><li>Diminue le risque de récidive de <span class=\"kw-chiffre\">40 %</span> et le risque de décès par cancer du sein de <span class=\"kw-chiffre\">30 %</span></li></ul>","suivi":"<p><strong>Soins supports</strong></p><ul><li><span class=\"kw-ttt\">Anti-ostéoporotiques</span> (bisphosphonates, dénosumab) : systématiques si <span class=\"kw-clinique\">métastases osseuses</span> (&gt;<span class=\"kw-chiffre\"> 50 %</span> des M+) ; indispensables si <span class=\"kw-alerte\">hypercalcémie</span></li><li><span class=\"kw-ttt\">Activité physique adaptée</span> : ↓ <span class=\"kw-def\">mortalité</span>, ↓ récidive, ↓ symptômes liés au cancer et aux traitements (cancers localisés)</li></ul><p><strong><span class=\"kw-def\">Surveillance</span> clinique</strong></p><ul><li>Tous les <span class=\"kw-chiffre\">3-6 mois</span> pendant les <span class=\"kw-chiffre\">5 premières années</span></li><li>Puis <span class=\"kw-chiffre\">1×/an</span> à vie ou jusqu’à la 10ᵉ année</li></ul><p><strong><span class=\"kw-def\">Surveillance</span> par imagerie</strong></p><ul><li>Mammographie bilatérale + <span class=\"kw-imagerie\">échographie</span> mammaire</li><li><span class=\"kw-chiffre\">1×/an</span> à vie ou jusqu’à la 10ᵉ année (sauf si mastectomie)</li></ul>"},"liensGlobaux":[{"href":"https://www.depistagesein.ca/classification-bi-rads/#:~:text=La%20classification%20BI%2DRADS%20","label":"https://www.depistagesein.ca/classification-bi-rads/#:~:text=La%20classification%20BI%2DRADS%20"},{"href":"https://cego-obgyn.fr/deuxieme-cycle/","label":"Collège CNGOF–CEGO · Référentiel, 6e édition 2024"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Symptôme ou dépistage ?","detail":"<ul><li>Nodule, écoulement, rétraction, inflammation ; histoire familiale.</li></ul>","branches":[{"label":"Symptôme/anomalie","to":"diagnostic"},{"label":"Asymptomatique","to":"depistage"}]},{"id":"depistage","kind":"decision","label":"Choisir le niveau de surveillance","detail":"<ul><li>Dépistage organisé à risque habituel ; parcours renforcé si risque élevé/génétique.</li></ul>","branches":[{"label":"Anomalie","to":"diagnostic"},{"label":"Normal","to":"suivi"}]},{"id":"diagnostic","kind":"decision","label":"Examen et imagerie diagnostique","detail":"<ul><li>Mammographie et/ou échographie selon âge et contexte ; IRM dans indications ciblées.</li></ul>","branches":[{"label":"Lésion suspecte","to":"biopsie"},{"label":"Résultat rassurant concordant","to":"suivi"},{"label":"Discordance","to":"expert"}]},{"id":"biopsie","kind":"decision","label":"Prélèvement percutané","detail":"<ul><li>Type de prélèvement guidé par la cible ; histologie avant stratégie thérapeutique.</li></ul>","branches":[{"label":"Cancer confirmé","to":"bilan"},{"label":"Bénin concordant","to":"suivi"},{"label":"Discordance","to":"expert"}]},{"id":"expert","kind":"finish","label":"Résoudre la discordance","detail":"<ul><li>Relecture, nouveau prélèvement ou avis spécialisé ; clinique suspecte malgré imagerie normale.</li></ul>","branches":[]},{"id":"bilan","kind":"decision","label":"Extension et biologie tumorale selon risque","detail":"<ul><li>Dissémination, histologie et récepteurs ; pas de bilan distant systématique pour toute petite tumeur.</li></ul>","branches":[{"label":"Décision en RCP","to":"traiter"}]},{"id":"traiter","kind":"finish","label":"Traitements locaux et systémiques adaptés","detail":"<ul><li>Chirurgie, radiothérapie, traitements médicaux et soins de support selon caractéristiques.</li></ul>","branches":[]},{"id":"suivi","kind":"finish","label":"Suivi approprié et consignes","detail":"<ul><li>Calendrier selon contexte ; consulter pour toute anomalie nouvelle.</li></ul>","branches":[]}]},"cards":[{"i":"10ea5d53a672","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Quelle est la procédure décisionnelle pour le traitement du cancer du sein ?","a":"<div class=\"notion-course\"><p>Toute décision thérapeutique pour le <span class=\"nc-red_bg\">cancer du sein</span> est prise en <strong>Réunion de Concertation Pluridisciplinaire (RCP)</strong> et est formalisée dans un <strong>Programme Personnalisé de Soins (PPS)</strong>. La prise en charge est à <strong>100% par la Sécurité Sociale</strong>.</p></div>"},{"i":"6a40ca251686","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Comment est gérée la chirurgie axillaire dans le traitement du cancer du sein ?","a":"<div class=\"notion-course\"><p>La chirurgie axillaire implique :</p><ul><li>Le <strong>ganglion sentinelle (GS)</strong> : identifié par injection de <strong><span class=\"nc-blue nc-bold\">gadolinium</span></strong> et/ou <strong>colorant</strong> (<span class=\"nc-blue nc-bold\">bleu patenté</span>, <span class=\"nc-blue nc-bold\">vert</span> <span class=\"nc-blue nc-bold\">d'indocyanine</span>). Il est indiqué pour les tumeurs <span class=\"nc-green_bg nc-bold\">cT1</span> à T3 en l'absence d'atteinte ganglionnaire prouvée en pré-opératoire, et permet d'éviter le curage axillaire s'il est négatif.</li><li>Le <strong>curage axillaire</strong> : indiqué si le ganglion sentinelle est métastatique, en cas de <span class=\"nc-red_bg\">tumeur cT4</span> ou d'atteinte ganglionnaire prouvée en cytologie.</li></ul></div>"},{"i":"8f85eda66b31","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Quels sont les types de chirurgie mammaire et leurs indications principales ?","a":"<div class=\"notion-course\"><p>Il existe deux types principaux de chirurgie mammaire :</p><ul><li><strong>Traitement conservateur</strong> (<span class=\"nc-pink_bg\">tumorectomie</span>, zonectomie ou <span class=\"nc-red_bg nc-bold\">mastectomie</span> partielle) avec <span class=\"nc-yellow_bg\">radiothérapie mammaire systématique</span> : indiqué pour les tumeurs de <strong>petite taille</strong> par rapport au volume du sein, uniques et accessibles.</li><li><strong>Traitement radical</strong> (<span class=\"nc-pink_bg\">mastectomie totale</span> : ablation du sein, du revêtement cutané et du mamelon) : indiqué pour le <span class=\"nc-red_bg\">cancer du sein </span><strong><span class=\"nc-red_bg\">inflammatoire</span></strong> (<span class=\"nc-red nc-bold\">T4d</span>), les lésions <strong>multifocales</strong> dans différents quadrants, les tumeurs <strong><span class=\"nc-pink nc-bold\">&gt; 5 cm</span></strong>, celles insuffisamment réduites par traitement <span class=\"nc-yellow_bg\">néoadjuvant</span>, ou en cas de contre-indication à la radiothérapie.</li></ul></div>"},{"i":"93bc658672b6","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Quels sont les objectifs généraux du traitement du cancer du sein ?","a":"<div class=\"notion-course\"><p>Les objectifs du traitement du <span class=\"nc-red_bg\">cancer du sein</span> sont multiples :</p><ul><li><strong>Exérèse</strong> de la tumeur.</li><li>Traitement des éventuelles <strong>métastases</strong>.</li><li>Réduction du <span class=\"nc-green_bg nc-bold\">risque</span> de <strong>récidive</strong>.</li><li><strong>Ralentissement de l'évolution</strong> de la maladie.</li><li>Amélioration de la <strong>qualité de vie</strong> du patient.</li></ul></div>"},{"i":"949227a54fcb","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Quelles sont les principales thérapies ciblées utilisées dans le cancer du sein et leurs spécificités ?","a":"<div class=\"notion-course\"><p>Les thérapies ciblées incluent :</p><ul><li>Le <strong>Trastuzumab</strong> (anti-HER2) : si <span class=\"nc-green_bg\">HER2+++</span> ou <span class=\"nc-yellow_bg\">HER2++</span> avec amplification FISH. Durée <strong>1 an</strong> (18 perfusions). Effet secondaire : <strong><span class=\"nc-red nc-bold\">cardiotoxique</span></strong>, nécessitant une surveillance de la <strong>FEVG</strong> (<span class=\"nc-blue nc-bold\">échographie</span> ou <span class=\"nc-blue nc-bold\">scintigraphie cardiaque</span>).</li><li>Le <strong><span class=\"nc-pink nc-bold\">T-DM1</span></strong> (trastuzumab couplé à l'emtansine) : en cas de résidu tumoral après chimio néoadjuvante.</li><li>Les <strong>anti-PARP</strong> : pour les cancers BRCA-mutés (germinale ou somatique).</li></ul></div>"},{"i":"9d87700af0d3","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Quand la chimiothérapie est-elle indiquée dans le traitement du cancer du sein et quel est son schéma habituel ?","a":"<div class=\"notion-course\"><p>La chimiothérapie, généralement une <strong>polychimiothérapie</strong> (anthracyclines + cyclophosphamide ± taxanes comme le docétaxel, paclitaxel), est indiquée pour environ <strong>30%</strong> des cancers infiltrants :</p><ul><li>En situation <strong>néoadjuvante</strong> (pré-opératoire) : pour les <span class=\"nc-red_bg\">cancers inflammatoires</span>, tumeurs &gt; 1 cm <span class=\"nc-red nc-bold\">triple négatif</span> ou HER2+, <span class=\"nc-red_bg\">envahissement ganglionnaire</span> massif (cN2/cN3), tumeurs limites pour la conservation.</li><li>En situation <strong>adjuvante</strong> (post-opératoire) : si facteurs de risque de mauvais pronostic (âge <span class=\"nc-pink nc-bold\">&lt; 35 ans</span>, T ≥ 2 cm, N+, <span class=\"nc-yellow_bg\">grade 3</span>, emboles, <span class=\"nc-yellow_bg\">Ki67 &gt; 20%</span>, RH−, HER2+, <span class=\"nc-blue_bg\">cancer inflammatoire</span>).</li></ul></div>"},{"i":"a0a5d1f5f00b","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Quand l'hormonothérapie est-elle indiquée dans le cancer du sein et quelles sont les molécules utilisées selon le statut ménopausique ?","a":"<div class=\"notion-course\"><p>L'hormonothérapie est indiquée si le cancer est <strong>RH+ (récepteurs hormonaux positifs : RO et/ou RP ≥ 10%)</strong>. Elle est <span class=\"nc-yellow_bg\">prescrite en situation </span><strong><span class=\"nc-yellow_bg\">adjuvante</span></strong> après les traitements initiaux, pour une <span class=\"nc-pink nc-bold\">durée minimale de </span><strong><span class=\"nc-pink nc-bold\">5 ans</span></strong>, parfois étendue à <span class=\"nc-pink nc-bold\">10 ans</span>.</p><ul><li><strong>Avant la ménopause</strong> : <strong>Tamoxifène</strong> (SERM) ± analogues LH-RH si &lt; 35 ans et facteurs de gravité.</li><li><strong><span class=\"nc-yellow_bg\">Après la ménopause</span></strong> : <strong>Inhibiteurs d'<span class=\"nc-pink nc-bold\">aromatase</span></strong> (<span class=\"nc-pink nc-bold\">anastrozole</span>, <span class=\"nc-pink nc-bold\">létrozole</span>, <span class=\"nc-pink nc-bold\">exémestane</span>). Le tamoxifène est possible en cas de contre-indication aux inhibiteurs d'<span class=\"nc-pink nc-bold\">aromatase</span>.</li></ul></div>"},{"i":"c300ec21f8e6","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Dans quelles situations la radiothérapie est-elle indiquée pour le cancer du sein ?","a":"<div class=\"notion-course\"><p>La radiothérapie est indiquée dans plusieurs situations :</p><ul><li><strong>Mammaire</strong> : systématique après traitement conservateur (radiothérapie externe + boost sur le lit opératoire).</li><li><strong>Pariétale</strong> : après <span class=\"nc-pink_bg\">mastectomie totale</span> si présence de facteurs de risque de mauvais pronostic (T <span class=\"nc-pink nc-bold\">&gt; 5 cm</span>, pN+, âge <span class=\"nc-pink nc-bold\">&lt; 35 ans</span>, <span class=\"nc-yellow_bg\">grade 3</span>, emboles tumoraux).</li><li><strong>Ganglionnaire</strong> : systématique si atteinte ganglionnaire axillaire (N+).</li></ul></div>"},{"i":"ce9bb7c4f400","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Quels sont les effets secondaires spécifiques du tamoxifène et des inhibiteurs d'aromatase ?","a":"<div class=\"notion-course\"><p>Les effets secondaires spécifiques sont :</p><ul><li><strong>Tamoxifène</strong> : <strong><span class=\"nc-red nc-bold\">MTEV</span></strong> (Maladie ThromboEmbolique Veineuse), <strong><span class=\"nc-red nc-bold\">cancer de l'endomètre</span></strong>, <span class=\"nc-blue_bg\">leucorrhées</span>, <span class=\"nc-orange_bg\">hypercalcémie</span>. Il est protecteur osseux.</li><li><strong>Inhibiteurs d'<span class=\"nc-pink nc-bold\">aromatase</span></strong> : <span class=\"nc-blue_bg\">Arthralgies</span>, <span class=\"nc-blue_bg\">myalgies</span>, <span class=\"nc-orange_bg\">dyslipidémie</span>, <span class=\"nc-orange_bg\">troubles de l'humeur</span>, <span class=\"nc-red_bg\">accentuation de la déminéralisation osseuse</span>. Ils sont contre-indiqués en monothérapie chez la femme non-ménopausée.</li></ul></div>"},{"i":"fc3b4bb34a06","n":312,"o":"312-12","u":"Prise en charge","t":"Connaître les objectifs et principes de traitement du cancer du sein","q":"Quelles sont les principales complications potentielles du curage axillaire ?","a":"<div class=\"notion-course\"><p>Les complications potentielles du curage axillaire incluent :</p><ul><li>Le <strong>lymphœdème du membre supérieur</strong>.</li><li>Les troubles sensitifs.</li><li>Le lymphocèle.</li><li>L'hématome.</li><li>L'<span class=\"nc-orange_bg\">enraidissement de l'épaule</span>.</li></ul></div>"},{"i":"0b6184b25965","n":312,"o":"312-4","u":"Physiopathologie","t":"Connaître l'histoire naturelle du cancer du sein et ses modes de dissémination","q":"Comment le carcinome in situ se distingue-t-il du carcinome invasif en termes de définition et de risque métastatique ?","a":"<div class=\"notion-course\"><ul><li>Le <strong><span class=\"nc-orange_bg\">carcinome in situ</span></strong> est une <span class=\"nc-green_bg\">évolution</span> intra-épithéliale (dans le canal ou le lobule) : il n'y a pas de <span class=\"nc-red nc-bold\">franchissement de la membrane basale</span> et le risque métastatique est <strong>nul</strong>.</li><li>Le <strong>carcinome invasif (infiltrant)</strong> implique le <span class=\"nc-red nc-bold\">franchissement de la membrane basale</span>, ce qui lui confère un <strong>risque métastatique présent</strong> par voies lymphatique et hématogène.</li></ul></div>"},{"i":"8283588a4dd0","n":312,"o":"312-4","u":"Physiopathologie","t":"Connaître l'histoire naturelle du cancer du sein et ses modes de dissémination","q":"Quelle est l'origine tissulaire du cancer du sein et quel est le rôle des œstrogènes dans sa carcinogenèse ?","a":"<div class=\"notion-course\"><p>Le <span class=\"nc-red_bg\">cancer du sein</span> naît des cellules de l'<strong>appareil sécrétoire du sein</strong> (<span class=\"nc-green_bg\">lobules</span> et <span class=\"nc-green_bg\">canaux</span> galactophores). La carcinogenèse est un processus multi-étapes, influencé par les <strong><span class=\"nc-pink_bg nc-bold\">œstrogènes</span></strong> dans 60-70 % des cas (cancer hormono-dépendant).</p></div>"},{"i":"9aa78c509a90","n":312,"o":"312-4","u":"Physiopathologie","t":"Connaître l'histoire naturelle du cancer du sein et ses modes de dissémination","q":"Quelles sont les particularités de dissémination ou de récidive pour les sous-types moléculaires de cancer du sein : lobulaire infiltrant, HER2+, et triple négatif ?","a":"<div class=\"notion-course\"><ul><li>Le <strong><span class=\"nc-orange_bg\">carcinome lobulaire infiltrant</span></strong> présente un <strong>tropisme péritonéal et pleural</strong> (carcinose).</li><li>Le sous-type <strong>HER2+</strong> a un <strong>tropisme cérébral</strong> (<span class=\"nc-red nc-bold\">SNC</span>) fréquent.</li><li>Le sous-type <strong><span class=\"nc-red nc-bold\">triple négatif</span></strong> est caractérisé par une <strong>récidive précoce</strong> (<span class=\"nc-pink nc-bold\">2-3 premières années</span>) et un mauvais pronostic.</li></ul></div>"},{"i":"c1d84a404d0e","n":312,"o":"312-4","u":"Physiopathologie","t":"Connaître l'histoire naturelle du cancer du sein et ses modes de dissémination","q":"Décrivez l'histoire naturelle du cancer du sein, de la cellule normale au carcinome invasif.","a":"<div class=\"notion-course\"><p>La cellule normale évolue en <strong><span class=\"nc-orange_bg\">carcinome in situ</span></strong>, où la membrane basale est intacte et il n'y a pas de métastases. Après franchissement de cette membrane basale, il devient un <strong>carcinome invasif</strong>, qui est alors capable de métastaser.</p></div>"},{"i":"e7e404ce3d36","n":312,"o":"312-4","u":"Physiopathologie","t":"Connaître l'histoire naturelle du cancer du sein et ses modes de dissémination","q":"Quelles sont les principales voies de dissémination du carcinome invasif du sein ?","a":"<div class=\"notion-course\"><p>Le carcinome invasif dissémine par :</p><ul><li>La <strong>voie lymphatique</strong>, atteignant principalement le <strong><span class=\"nc-purple nc-bold\">creux axillaire</span></strong> (relais principal), puis les <span class=\"nc-purple_bg\">ganglions</span> <span class=\"nc-purple_bg nc-bold\">sus-</span> et <span class=\"nc-purple_bg nc-bold\">sous-claviculaires</span>, et la <span class=\"nc-purple_bg nc-bold\">chaîne mammaire interne</span>.</li><li>La <strong>voie hématogène</strong>, touchant préférentiellement l'<strong>os</strong>, le <strong>poumon</strong>, et le <strong>foie</strong>.</li></ul></div>"},{"i":"2fb021ca617f","n":312,"o":"312-5","u":"Diagnostic positif","t":"Connaître les différentes modalités de dépistage","q":"Quel est le piège diagnostique primordial à connaître concernant le dépistage du cancer du sein ?","a":"<div class=\"notion-course\"><p>Un <strong>dépistage n'est jamais réalisé sur un sein déjà symptomatique</strong>. En présence de tout signe clinique suspect (<strong>nodule, écoulement, <span class=\"nc-blue_bg\">rétraction cutanée</span></strong>), il faut basculer immédiatement vers une <strong>démarche diagnostique</strong> et ne pas considérer cela comme du dépistage.</p></div>"},{"i":"76c6e7f7062e","n":312,"o":"312-5","u":"Diagnostic positif","t":"Connaître les différentes modalités de dépistage","q":"Quelle est la stratégie de dépistage du cancer du sein pour une femme considérée à haut risque, c'est-à-dire avec un antécédent personnel ou familial identifié ?","a":"<div class=\"notion-course\"><p>Pour les femmes à haut risque (ex: antécédent personnel d'<span class=\"nc-orange_bg\">hyperplasie atypique</span>, de <span class=\"nc-red_bg\">carcinome lobulaire in situ</span>, de <span class=\"nc-red_bg\">carcinome canalaire in situ</span>, ou antécédent d'irradiation thoracique haute dose pour un Hodgkin), la stratégie de dépistage est <strong>individuelle</strong>. Elle repose sur une <strong><span class=\"nc-blue_bg\">mammographie</span> <span class=\"nc-pink nc-bold\">annuelle</span></strong> associée à une <strong><span class=\"nc-blue_bg\">échographie</span> <span class=\"nc-pink nc-bold\">annuelle</span></strong>.</p></div>"},{"i":"b0e068206283","n":312,"o":"312-5","u":"Diagnostic positif","t":"Connaître les différentes modalités de dépistage","q":"Comment est défini le dépistage du cancer du sein pour la population générale et quelle est la modalité principale préconisée ?","a":"<div class=\"notion-course\"><p>Pour les <strong>femmes âgées de 50 à 74 ans sans facteur de risque particulier</strong>, le dépistage s'inscrit dans un <strong>programme organisé</strong>. Il consiste en une <strong><span class=\"nc-blue_bg\">mammographie bilatérale 2 incidences</span></strong> (<span class=\"nc-blue nc-bold\">oblique externe</span> et cranio-caudale) réalisée <strong>tous les <span class=\"nc-pink nc-bold\">2 ans</span></strong>.</p></div>"},{"i":"c65f6c0914ca","n":312,"o":"312-5","u":"Diagnostic positif","t":"Connaître les différentes modalités de dépistage","q":"En présence d'une mutation génétique avérée de type BRCA1/2, TP53 ou PALB2, quelle est la stratégie de dépistage du cancer du sein mise en place ?","a":"<div class=\"notion-course\"><p>Pour les femmes porteuses de mutations génétiques délétères (BRCA1/2, <span class=\"nc-red_bg nc-bold\">TP53</span>, PALB2, etc.), un <strong>programme personnalisé</strong> est instauré. Il comprend un <strong>examen clinique bisannuel dès 20 ans</strong> et une surveillance <span class=\"nc-pink nc-bold\">annuelle</span> plus intensive entre 30 et 65 ans, associant <strong>IRM mammaire, <span class=\"nc-blue_bg\">mammographie</span> et <span class=\"nc-blue_bg\">échographie</span></strong>.</p></div>"},{"i":"42f928fea87b","n":312,"o":"312-6","u":"Diagnostic positif","t":"Connaître les présentations cliniques des tumeurs du sein","q":"Quelles modifications cutanées mammaires doivent faire suspecter une tumeur du sein ?","a":"<div class=\"notion-course\"><p>Les modifications cutanées suspectes sont :</p><ul><li><span class=\"nc-blue_bg\">Rétraction cutanée</span>, fossette, méplat (recherchés à l'éclairage jour frisant, bras pendants puis relevés)</li><li><strong><span class=\"nc-red_bg\">Squirrhe mammaire</span></strong> (<span class=\"nc-green_bg\">tumeur</span> dure avec épaississement et/ou bourgeonnement)</li><li><span class=\"nc-red_bg\">Ulcération cutanée</span>, <span class=\"nc-red_bg\">nodules de perméation</span></li><li><span class=\"nc-blue_bg\">Empâtement</span>, <span class=\"nc-red_bg\">lésion croûteuse</span></li><li>Signes d'inflammation (dans le cadre d'un <span class=\"nc-blue_bg\">cancer inflammatoire</span>) : placard érythémateux chaud, œdème cutané avec aspect de « <strong>peau d'orange</strong> » sur <strong><span class=\"nc-red nc-bold\">≥ 1/3</span></strong><span class=\"nc-red nc-bold\"> du sein</span> et d'évolution rapide en quelques semaines.</li></ul></div>"},{"i":"60a8646fa9e0","n":312,"o":"312-6","u":"Diagnostic positif","t":"Connaître les présentations cliniques des tumeurs du sein","q":"Comment définit-on un cancer du sein inflammatoire (T4d) et quels en sont les signes cliniques ?","a":"<div class=\"notion-course\"><p>Le <span class=\"nc-red_bg\">cancer du sein</span> inflammatoire (<span class=\"nc-red nc-bold\">T4d</span>) est défini par l'association de <strong>quatre critères</strong> :</p><ul><li>Un <strong>placard érythémateux chaud</strong></li><li>Un <strong>œdème cutané</strong> avec un aspect de « <strong>peau d'orange</strong> »</li><li>La présence de ces signes sur <strong><span class=\"nc-red nc-bold\">≥ 1/3</span></strong><span class=\"nc-red nc-bold\"> du sein</span></li><li>Une <strong>évolution rapide</strong> en quelques semaines</li></ul><p>Il nécessite une prise en charge spécifique avec mastectomie + curage + <span class=\"nc-pink\">chimiothérapie néoadjuvante</span>, quel que soit le sous-type.</p></div>"},{"i":"67b3bd61c6ed","n":312,"o":"312-6","u":"Diagnostic positif","t":"Connaître les présentations cliniques des tumeurs du sein","q":"Quels sont les signes cliniques suspect d'un écoulement mamelonnaire ?","a":"<div class=\"notion-course\"><p>Un <span class=\"nc-blue_bg\">écoulement mamelonnaire</span> est suspect s'il est :</p><ul><li>Apparition <strong><span class=\"nc-red nc-bold\">récente</span></strong></li><li><strong><span class=\"nc-red nc-bold\">Spontané</span></strong></li><li><strong><span class=\"nc-red nc-bold\">Unilatéral</span></strong></li><li><strong><span class=\"nc-red nc-bold\">Unipore</span></strong></li><li>De couleur <strong><span class=\"nc-red nc-bold\">claire</span></strong>, <strong><span class=\"nc-red nc-bold\">jaune</span> séreux</strong>, <strong><span class=\"nc-red nc-bold\">rouge</span> sanglant</strong> ou <strong><span class=\"nc-red nc-bold\">noir</span></strong></li></ul></div>"},{"i":"8fb2973a7209","n":312,"o":"312-6","u":"Diagnostic positif","t":"Connaître les présentations cliniques des tumeurs du sein","q":"Quelle est la conduite à tenir face à un nodule du sein chez une femme ménopausée ?","a":"<div class=\"notion-course\"><p>L'apparition d'un <strong>nodule du sein</strong> chez une femme ménopausée doit faire suspecter un <strong><span class=\"nc-red_bg\">cancer du sein</span></strong> jusqu'à preuve du contraire.</p></div>"},{"i":"d72813c16702","n":312,"o":"312-6","u":"Diagnostic positif","t":"Connaître les présentations cliniques des tumeurs du sein","q":"Quelles sont les modifications du mamelon pouvant évoquer une tumeur du sein ?","a":"<div class=\"notion-course\"><p>Les modifications du mamelon à surveiller sont :</p><ul><li><strong>Déviation</strong>, <strong>invagination</strong> ou <strong>rétraction</strong> du mamelon</li><li>Un <span class=\"nc-blue_bg\">aspect </span><strong><span class=\"nc-blue_bg\">eczématiforme</span></strong><span class=\"nc-blue_bg\"> du mamelon</span>, d'autant plus s'il est persistant et unilatéral, qui doit faire évoquer une <strong><span class=\"nc-orange nc-bold\">maladie de Paget</span> du sein</strong> (nécessitant une punch-biopsie cutanée systématique).</li></ul></div>"},{"i":"24c35e79726a","n":312,"o":"312-8","u":"Examens complémentaires","t":"Connaître les indications de la mammographie","q":"Dans quel contexte la mammographie est-elle indiquée en première intention pour le dépistage organisé du cancer du sein ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-blue_bg\">mammographie</span> est indiquée en première intention dans le cadre du <strong>dépistage organisé</strong> chez les femmes âgées de <strong>50 à 74 ans</strong>, tous les <strong><span class=\"nc-pink nc-bold\">2 ans</span></strong>, en l'absence de signes cliniques.</p></div>"},{"i":"7d98d123852e","n":312,"o":"312-8","u":"Examens complémentaires","t":"Connaître les indications de la mammographie","q":"Quand la mammographie est-elle indiquée dans le cadre d'un dépistage individuel ou d'une démarche diagnostique ?","a":"<div class=\"notion-course\"><p>Elle est indiquée annuellement en <strong>dépistage individuel</strong> chez les femmes à <strong>haut risque</strong> (antécédents personnels/familiaux, irradiation thoracique, lésion à risque). Elle est également indiquée en <strong>démarche diagnostique</strong> devant <strong><span class=\"nc-yellow_bg\">toute anomalie clinique mammaire</span></strong> (nodule, écoulement suspect, rétraction, modification <span class=\"nc-red_bg nc-bold\">cutanée</span>).</p></div>"},{"i":"bd80081aa249","n":312,"o":"312-8","u":"Examens complémentaires","t":"Connaître les indications de la mammographie","q":"Dans quelles situations la mammographie est-elle contre-indiquée ou remplacée en première intention ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-blue_bg\">mammographie</span> est <strong>contre-indiquée</strong> chez la <strong>femme très jeune (<span class=\"nc-pink nc-bold\">&lt; 30 ans</span>)</strong> et chez la <strong>femme enceinte</strong> (<span class=\"nc-green\">seins denses</span> non lisibles). Dans ces cas, l'<strong><span class=\"nc-blue_bg\">échographie</span></strong> remplace la <span class=\"nc-blue_bg\">mammographie</span> en première intention.</p></div>"},{"i":"d97017374caf","n":312,"o":"312-8","u":"Examens complémentaires","t":"Connaître les indications de la mammographie","q":"Quelles sont les indications de la mammographie dans le suivi du cancer du sein ?","a":"<div class=\"notion-course\"><p>La mammographie est systématiquement indiquée en <strong>bilan préthérapeutique</strong> (<span class=\"nc-blue_bg\">bilatérale</span> avant traitement d'un <span class=\"nc-red_bg\">cancer du sein</span>) et pour la <strong>surveillance post-traitement</strong> (1 fois/an à vie ou jusqu'à la 10e année, sauf en cas de <span class=\"nc-pink_bg\">mastectomie totale</span>).</p></div>"},{"i":"cf4ad46de85b","n":312,"o":"312-1","u":"Epidémiologie","t":"Connaître l'épidémiologie des tumeurs du sein","q":"Que retenir concernant l'épidémiologie des tumeurs du sein ?","a":"<div class=\"notion-course\"><p>Le <span class=\"nc-red_bg\">cancer du sein</span> est le <span><span class=\"nc-yellow_bg\">cancer le plus fréquent chez la femme</span></span> en France et le <span>2ème cancer tous sexes confondus</span>. Il représente la <span><span class=\"nc-red nc-bold\">1ère cause de mortalité par cancer chez la femme</span></span>, malgré une <span><span class=\"nc-green_bg\">mortalité</span></span><span class=\"nc-green_bg\"> en diminution</span> grâce au <span>dépistage</span> et aux <span>progrès thérapeutiques</span>.</p>\n      <table>\n        <thead>\n          <tr><th>Paramètre</th><th>Valeur (France)</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span>Incidence</span> (2018)</td><td><span>~58 500 nouveaux cas/an</span> — <span><span class=\"nc-red_bg\">incidence</span></span><span class=\"nc-red_bg\"> en augmentation</span></td></tr>\n          <tr><td><span>Prévalence</span></td><td><span>650 000 à 900 000</span> femmes</td></tr>\n          <tr><td>Risque cumulé vie entière</td><td><span>~1 femme sur 8 à 10</span> développera un <span class=\"nc-red_bg\">cancer du sein</span></td></tr>\n          <tr><td>Âge médian au diagnostic</td><td><span><span class=\"nc-pink nc-bold\">63 ans</span></span> — moitié des cas entre <span>45 et 65 ans</span></td></tr>\n          <tr><td>Âge médian au décès</td><td><span><span class=\"nc-pink nc-bold\">74 ans</span></span></td></tr>\n          <tr><td><span>Mortalité</span> (2018)</td><td><span>~12 000 décès/an</span> — en diminution</td></tr>\n          <tr><td><span class=\"nc-green_bg nc-bold\">Survie</span> <span class=\"nc-green_bg nc-bold\">globale</span> à <span>5 ans</span></td><td><span>~90 %</span> (forte hétérogénéité selon sous-type et <span>stade</span>)</td></tr>\n          <tr><td>Sexe</td><td><span>&gt; 99 %</span> des cas chez la femme — existe chez l'homme (rare)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> 1<sup>er</sup> en <span>incidence</span> + <span><span class=\"nc-red nc-bold\">1</span><sup><span class=\"nc-red nc-bold\">ère</span></sup><span class=\"nc-red nc-bold\"> cause de mortalité par cancer chez la femme</span></span>. Couple incidence ↑ / <span class=\"nc-green nc-bold\">mortalité</span> ↓ = succès du <span>dépistage organisé</span> (<span><span class=\"nc-pink nc-bold\">50-74 ans</span></span>) et des <span>thérapies ciblées</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — Epidémiologie cancers</em></p></div>"},{"i":"2d4cd86c4023","n":312,"o":"312-2","u":"Epidémiologie","t":"Connaître les facteurs de risque des tumeurs du sein","q":"Que retenir concernant les facteurs de risque des tumeurs du sein ?","a":"<div class=\"notion-course\"><p>Maladie <span>multifactorielle</span> : l'âge, l'exposition hormonale endogène et exogène, les antécédents personnels et familiaux et le mode de vie se combinent. L'identification du niveau de risque guide la <span>stratégie de dépistage</span> (organisé, individuel, ou très ciblé pour les <span>mutations délétères</span>).</p>\n      <table>\n        <thead>\n          <tr><th>Catégorie</th><th><span>Facteurs de risque</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Âge</td>\n            <td><span>Moitié des cas entre 45 et 65 ans</span> — l'âge est le <span>FDR principal</span> de la population générale.</td>\n          </tr>\n          <tr>\n            <td>Exposition hormonale</td>\n            <td>\n              <strong>Imprégnation œstrogénique longue :</strong>\n              <ul>\n                <li>Puberté précoce (<span>&lt; 12 ans</span>)</li>\n                <li>Ménopause tardive (<span>&gt; 55 ans</span>)</li>\n                <li>1<sup>ère</sup> <span>grossesse</span> tardive (<span>&gt; 30 ans</span>)</li>\n                <li><span>Pauciparité, nulliparité</span></li>\n                <li><span><span class=\"nc-green_bg\">Absence d'allaitement</span></span></li>\n              </ul>\n              <strong>Traitements hormonaux :</strong>\n              <ul>\n                <li><span>Contraception œstro-progestative</span> (RR <span>1,04</span> — sur-risque faible)</li>\n                <li><span>THM</span> dépend du schéma et de la durée</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td>ATCD personnels</td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-orange_bg\">Carcinome in situ</span></span> (CCIS ou CLIS)</li>\n                <li><span><span class=\"nc-orange_bg\">Hyperplasie atypique</span></span> (canalaire ou lobulaire)</li>\n                <li><span><span class=\"nc-yellow_bg\">Mastopathie à risque histologique</span></span></li>\n                <li><span>Radiothérapie thoracique haute dose</span> (Hodgkin avant <span>30 ans</span>)</li>\n                <li><span>ATCD personnel de <span class=\"nc-red_bg\">cancer du sein</span></span> : <span>terrain</span> croisé avec cancers de l'<span>endomètre</span> et de l'<span><span class=\"nc-orange nc-bold\">ovaire</span></span> (mutations BRCA) → <span><span class=\"nc-red nc-bold\">examen gynécologique systématique</span></span> à toute <span>consultation de suivi</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td>ATCD familiaux</td>\n            <td>Tenir compte du degré de parenté, de l'âge de survenue, de la bilatéralité et de la multifocalité. Le <span>score d'Eisinger</span> gradue le risque familial : <span>≥ 3</span> = indication formelle de <span>consultation d'oncogénétique</span>.</td>\n          </tr>\n          <tr>\n            <td><span>Génétique</span></td>\n            <td><span>Syndrome sein-<span class=\"nc-orange nc-bold\">ovaire</span></span> (BRCA1/2,<span> 5-10 %</span> des cancers du sein) ; autres : <em><span class=\"nc-red_bg nc-bold\">TP53</span></em> (Li-Fraumeni), <em>CDH1</em>, <em>PALB2</em>, <em>CHEK2</em>, <em>ATM</em>, <em>PTEN</em> (Cowden), <em>STK11</em> (Peutz-Jeghers).</td>\n          </tr>\n          <tr>\n            <td>Mode de vie</td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-yellow_bg\">Alcool</span></span>, <span>tabac</span></li>\n                <li><span><span class=\"nc-yellow_bg\">Surpoids / obésité</span></span> (surtout post-ménopause)</li>\n                <li><span><span class=\"nc-blue_bg\">Sédentarité</span></span></li>\n                <li><span class=\"nc-blue_bg\">Haut niveau socio-économique</span> (biais de <span>dépistage</span>)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le sur-risque attribué à la contraception œstro-progestative est <span>faible</span> (RR 1,04) et ne contre-indique pas la prescription chez une femme sans autre FDR. À l'inverse, une <span>irradiation thoracique pour maladie de Hodgkin avant 30 ans</span> impose un <span>dépistage</span> individuel renforcé (mammo + <span>IRM</span> annuelles dès <span>30 ans</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception</em></p></div>"},{"i":"1d8bf46f67b1","n":312,"o":"312-3","u":"Physiopathologie","t":"Connaître les prédispositions génétiques du cancer du sein","q":"Que retenir concernant les prédispositions génétiques du cancer du sein ?","a":"<div class=\"notion-course\"><p>Les prédispositions héréditaires expliquent <span>5-10 %</span> des cancers du <span class=\"nc-orange nc-bold\">sein</span> et <span>20 %</span> des cancers du <span class=\"nc-orange nc-bold\">sein</span> familiaux. La mutation la plus fréquente porte sur les gènes <span>BRCA1</span> (chromosome 17) et <span>BRCA2</span> (chromosome 13), <span>gènes suppresseurs de tumeurs</span> codant pour des protéines de la <span>réparation de l'ADN par recombinaison homologue</span>. Transmission <span>autosomique dominante</span>.</p>\n      <table>\n        <thead>\n          <tr><th>Item</th><th>BRCA1 / BRCA2</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Mode de transmission</td><td>Autosomique dominante</td></tr>\n          <tr><td>Mécanisme</td><td>Hétérozygotie constitutionnelle + 2<sup>e</sup> mutation somatique sur le brin sain → déficit de la réparation des cassures double-brin → phénotype <span>HRD</span> (<em>Homologous Recombination Deficient</em>)</td></tr>\n          <tr><td>Risque cumulé <span class=\"nc-red_bg\">cancer du sein</span></td><td><span>60-80 %</span> (âge précoce, <span class=\"nc-pink nc-bold\">multifocal</span>, bilatéral fréquents)</td></tr>\n          <tr><td>Risque cumulé cancer de l'<span class=\"nc-orange nc-bold\">ovaire</span></td><td><span>~60 %</span> (BRCA1) ; <span>~30 %</span> (BRCA2)</td></tr>\n          <tr><td>Autres cancers (BRCA2)</td><td><span>Mélanome</span>, pancréas, prostate, sein chez l'<span class=\"nc-pink nc-bold\">homme</span></td></tr>\n        </tbody>\n      </table>\n      <h4>Indications d'oncogénétique (cas-index) — ATCD personnels</h4>\n      <table>\n        <thead>\n          <tr><th>Critère</th><th>Pourquoi suspect</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"nc-red_bg\">Cancer du sein</span> <span><span class=\"nc-pink nc-bold\">≤ 40 ans</span></span></td><td>Survenue jeune = forte présomption <span>héréditaire</span></td></tr>\n          <tr><td>Sein + <span><span class=\"nc-orange nc-bold\">ovaire</span></span> chez la même patiente</td><td>Syndrome <span>sein-<span class=\"nc-orange nc-bold\">ovaire</span></span> (BRCA1/2)</td></tr>\n          <tr><td><span class=\"nc-red_bg\">Cancer du sein</span> <span><span class=\"nc-pink nc-bold\">multifocal</span></span> ou <span>bilatéral</span></td><td>Phénotype BRCA-like</td></tr>\n          <tr><td><span class=\"nc-red_bg\">Cancer du sein</span> chez l'<span><span class=\"nc-pink nc-bold\">homme</span></span></td><td>Évoque BRCA2</td></tr>\n          <tr><td><span class=\"nc-red_bg\">Cancer du sein</span> de type <span><span class=\"nc-red nc-bold\">médullaire</span></span></td><td>Forme histologique évocatrice de BRCA1</td></tr>\n          <tr><td><span><span class=\"nc-red nc-bold\">Triple négatif</span></span> avant <span>60 ans</span></td><td>Sous-type fortement associé à BRCA1</td></tr>\n        </tbody>\n      </table>\n      <p><strong>ATCD familiaux :</strong></p>\n      <ul>\n        <li><span>≥ 3</span> cancers du sein chez apparentées au 1<sup>er</sup> ou 2<sup>e</sup> degré</li>\n        <li><span>≥ 2</span> cancers du sein chez apparentées de <span><span class=\"nc-pink nc-bold\">&lt; 70 ans</span></span>, dont <span>≥ 1</span> à <span><span class=\"nc-pink nc-bold\">&lt; 50 ans</span></span></li>\n        <li><span>≥ 1</span> <span class=\"nc-red_bg\">cancer du sein</span> + 1 cancer de l'<span class=\"nc-orange nc-bold\">ovaire</span> au 1<sup>er</sup> degré</li>\n      </ul>\n      <h4>Mesures préventives en cas de mutation</h4>\n      <table>\n        <thead>\n          <tr><th>Mesure</th><th>Âge</th><th>Fréquence</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span>Examen clinique des seins</span></td><td>Dès <span>20 ans</span></td><td>Bisannuel</td></tr>\n          <tr><td><span>IRM mammaire</span> + <span>mammographie</span> (<span>incidence</span> oblique unique) ± écho</td><td><span>30 - 65 ans</span></td><td><span class=\"nc-pink nc-bold\">Annuelle</span></td></tr>\n          <tr><td><span>Mastectomie bilatérale prophylactique</span></td><td>Envisagée dès <span>30 ans</span></td><td>—</td></tr>\n          <tr><td><span>Surveillance</span> gynécologique ± écho pelvienne</td><td>Dès <span>30-35 ans</span></td><td><span class=\"nc-pink nc-bold\">Annuelle</span></td></tr>\n          <tr><td><span>Annexectomie bilatérale prophylactique</span></td><td>BRCA1 : <span>40-41 ans</span> ; BRCA2 : <span>45-47 ans</span></td><td>—</td></tr>\n        </tbody>\n      </table>\n      <h4>Intérêt thérapeutique : anti-PARP</h4>\n      <p>Les cancers BRCA-mutés sont <span>plus chimiosensibles</span> que les cancers sporadiques. La prescription des <span>inhibiteurs de PARP</span> (anti-PARP) est conditionnée à la présence d'une mutation BRCA (germinale ou somatique) dans les cancers du <strong><span class=\"nc-orange nc-bold\">sein</span></strong>, de la <strong>prostate</strong>, de l'<strong><span class=\"nc-orange nc-bold\">ovaire</span></strong> et du <strong>pancréas</strong>.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le <span>score d'Eisinger</span> (seuil <span>≥ 3</span>) déclenche la <span>consultation d'oncogénétique</span>. Le diagnostic d'une mutation conditionne à la fois la <span>surveillance individualisée</span>, la <span>chirurgie prophylactique</span> et la <span>prescription d'anti-PARP</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 306 — Tumeur ovaire · 300 — Tumeur col-corps utérin</em></p></div>"},{"i":"638e367bbcb0","n":312,"o":"312-7","u":"Contenu multimédia","t":"Photographies de lésions/anomalies cutanées sein","q":"Que retenir concernant photographies de lésions/anomalies cutanées sein ?","a":"<div class=\"notion-course\"><p>Cet objectif est un objectif de <span>reconnaissance visuelle</span> : à l'EDN, les <span>vignettes</span> peuvent présenter une photographie clinique du sein et demander d'identifier le <span>signe cutané</span> et le diagnostic évoqué. La sémiologie textuelle à connaître recouvre les principales présentations visibles à l'<span>inspection</span>.</p>\n      <h4>Cinq signes cutanés à reconnaître</h4>\n      <table>\n        <thead>\n          <tr><th>Signe</th><th>Description</th><th>Diagnostic évoqué</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span><span class=\"nc-orange nc-bold\">Maladie de Paget</span></span> du mamelon</td>\n            <td><span class=\"nc-blue_bg\">Aspect </span><strong><span class=\"nc-blue_bg\">eczématiforme</span></strong><span class=\"nc-blue_bg\"> du mamelon</span> et de l'aréole : <span>érythème, érosion, croûtes, prurit</span>, unilatéral et persistant malgré les soins locaux</td>\n            <td><span>Carcinome canalaire associé</span> (in situ ou invasif) → <span>punch-biopsie <span class=\"nc-red_bg nc-bold\">cutanée</span></span></td>\n          </tr>\n          <tr>\n            <td><span>Peau d'orange</span></td>\n            <td><span>Œdème cutané dermique</span> donnant un aspect d'orifices pilo-sébacés saillants — souvent associé à <span>érythème et chaleur</span></td>\n            <td><span><span class=\"nc-red_bg\">Cancer du sein</span> inflammatoire (<span class=\"nc-red nc-bold\">T4d</span>)</span></td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-blue_bg\">Rétraction cutanée</span></span></td>\n            <td><span>Fossette ou méplat localisé</span> en regard d'une tumeur sous-jacente — visible à l'inspection bras relevés, parfois uniquement à l'éclairage frisant</td>\n            <td><span>Cancer <span class=\"nc-red nc-bold\">infiltrant</span></span> avec <span>adhérence <span class=\"nc-red_bg nc-bold\">cutanée</span></span></td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-red_bg\">Ulcération cutanée</span></span></td>\n            <td><span>Perte de substance bourgeonnante ou nécrotique</span>, parfois associée à des <span><span class=\"nc-red_bg\">nodules de perméation</span></span></td>\n            <td>Cancer évolué (souvent <span>T4b</span>) découvert tardivement</td>\n          </tr>\n          <tr>\n            <td><span>Écoulement sanglant</span></td>\n            <td><span>Goutte de sang spontanée, unilatérale, <span class=\"nc-red nc-bold\">unipore</span></span> — visible à l'inspection ou provoquée par pression douce</td>\n            <td><span>Cancer canalaire</span> ou <span>papillome intra-canalaire</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">Photographies cliniques disponibles dans les illustrations de cet objectif : rétraction et anomalie <span class=\"nc-red_bg nc-bold\">inflammatoire</span>. Elles complètent l’examen clinique et ne remplacent pas la confirmation diagnostique.</div></div>"},{"i":"9ee282fda554","n":312,"o":"312-9","u":"Examens complémentaires","t":"Connaître les indications de la biopsie mammaire","q":"Que retenir concernant les indications de la biopsie mammaire ?","a":"<div class=\"notion-course\"><ul><li>Les lésions ACR/BI-RADS 4 ou 5 nécessitent une preuve histologique, habituellement par prélèvement percutané guidé. ACR 0 impose un complément d’imagerie ; ACR 3 une surveillance rapprochée dans une situation concordante.</li><li>Microbiopsie surtout pour une masse repérée à l’échographie ; macrobiopsie notamment pour microcalcifications ou certaines lésions non massiques, guidée par la technique qui montre la lésion.</li><li>La cytoponction seule ne fournit pas les mêmes informations architecturales qu’une biopsie. L’histologie précise type, grade et biomarqueurs nécessaires au traitement.</li><li>Toujours confronter clinique, imagerie et histologie. Une lésion cliniquement suspecte ou une discordance ne doit pas être classée rassurante sur un résultat d’imagerie/biopsie isolé.</li><li>Si résultat bénin concordant : suivi adapté ; si prélèvement insuffisant ou discordant : nouvelle investigation/prélèvement. La catégorie ACR n’est pas à elle seule un diagnostic histologique.</li></ul></div>"},{"i":"ce58137b23ae","n":312,"o":"312-10","u":"Définition","t":"Connaître les principaux types de lésions bénignes et de tumeurs malignes du sein","q":"Que retenir concernant les principaux types de lésions bénignes et de tumeurs malignes du sein ?","a":"<div class=\"notion-course\"><p>Trois grandes catégories d'entités à distinguer : <strong>lésions bénignes simples</strong> (pas de risque de cancer), <strong>lésions bénignes à risque</strong> (<span>chirurgie</span> souvent indiquée) et <strong>tumeurs malignes</strong> (<span>in situ</span> <span>vs</span> <span>invasif</span>).</p>\n      <h4>Lésions bénignes simples — pas de sur-risque de cancer</h4>\n      <table>\n        <thead>\n          <tr><th>Entité</th><th>Caractéristiques cliniques</th><th>Risque / PEC</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span><span class=\"nc-orange_bg\">Adénofibrome</span></span> (fibroadénome)</td>\n            <td><span class=\"nc-green_bg\">Tumeur</span> la plus fréquente de la <span>femme <span class=\"nc-pink nc-bold\">&lt; 30 ans</span></span>. <span>Prolifération mixte épithéliale et conjonctive</span>. <span>Nodule unique ou multiple, <span class=\"nc-green\">indolore</span>, bien limité, <span class=\"nc-green\">mobile</span>, <span class=\"nc-green\">ferme</span> « caoutchouteux »</span>, <span><span class=\"nc-pink\">&lt; 3 cm</span></span>. Écho : <span>masse</span> <span><span class=\"nc-blue nc-bold\">hypoéchogène</span></span>, ovale, bords réguliers, <span class=\"nc-blue_bg\">grand axe parallèle à la peau</span>, <span><span class=\"nc-green_bg\">macrocalcifications</span></span> possibles.</td>\n            <td>Pas de sur-risque. <span>Surveillance <span class=\"nc-pink nc-bold\">annuelle</span> clinique</span> ± écho. <span>Microbiopsie</span> si <span><span class=\"nc-pink\">&gt; 30 ans</span></span>, imagerie atypique, croissance rapide. <span>Chirurgie</span> si gêne, <span class=\"nc-blue\">douleur</span>, <span>lésion</span> volumineuse, ou après <span>35 ans</span>.</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-orange_bg\">Mastopathie fibrokystique</span> (MFK)</span></td>\n            <td>Maladie bénigne la plus fréquente entre <span><span class=\"nc-pink nc-bold\">35-50 ans</span></span>. <span>Mastodynies cycliques</span> pré-menstruelles, <span>placards granuleux sensibles</span>, <span>kystes mammaires</span>, <span>écoulement jaune/verdâtre/blanchâtre</span>. <span>Échographie</span> : Kystes <span class=\"nc-green_bg\">simples : </span><span><span class=\"nc-green_bg\">masse</span></span> <span><span class=\"nc-green_bg\">anéchogène</span></span> <span class=\"nc-green\">arrondie</span> bien limitée <span>avec <span class=\"nc-green_bg\">renforcement postérieur</span></span>. <span class=\"nc-yellow_bg\">Kystes atypiques</span> : parois <span class=\"nc-red_bg\">épaisses</span> <span class=\"nc-red_bg\">irrégulières</span>, <span class=\"nc-red_bg\">végétations</span> <span class=\"nc-red_bg\">intrakystiques</span>.</td>\n            <td>Pas de sur-<span class=\"nc-green_bg nc-bold\">risque</span> (sauf <span class=\"nc-orange_bg\">hyperplasie atypique</span> associée). PEC : <span>règles hygiéno-diététiques</span> (soutien-gorge, ↓ tabac/café/<span class=\"nc-yellow_bg\">alcool</span>), <span><span class=\"nc-pink\">progestatifs</span></span> en 2<sup>e</sup> partie de cycle. <span>Chirurgie</span> rare (<span class=\"nc-red\">kyste atypique</span>, récidive après ponctions itératives).</td>\n          </tr>\n          <tr>\n            <td><span>Hamartome</span></td>\n            <td><span>Lésion</span> rare, tissu glandulaire + fibreux + adipeux mêlés</td>\n            <td>Pas de <span>chirurgie</span> ni de <span>surveillance</span> spécifique</td>\n          </tr>\n          <tr>\n            <td><span>Cytostéatonécrose</span></td>\n            <td>Autodigestion du tissu adipeux par les lipases adipocytaires. Souvent <span>post-traumatisme</span>, <span>post-chirurgie ou post-radiothérapie</span>. Aspect parfois inquiétant (<span class=\"nc-blue_bg\">rétraction cutanée</span>, densification, inflammation)</td>\n            <td>Imagerie redresse le diagnostic. Régression spontanée dans <span>90 %</span> des cas. <span>Surveillance</span> simple, pas de <span>chirurgie</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Lésions bénignes à risque de cancer — <span>chirurgie</span> souvent indiquée</h4>\n      <table>\n        <thead>\n          <tr><th>Entité</th><th>Caractéristiques</th><th>PEC</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span><span class=\"nc-orange_bg\">Hyperplasie canalaire atypique</span></span></td>\n            <td>RR <span>×4-5</span>. Souvent découverte sur microbiopsie pour <span>microcalcifications</span></td>\n            <td><span>Exérèse chirurgicale</span> recommandée (risque de sous-estimation d'une <span>lésion</span> cancéreuse sous-jacente)</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-orange_bg\">Hyperplasie lobulaire atypique</span> / <span class=\"nc-red_bg\">Carcinome lobulaire in situ</span> (CLIS)</span></td>\n            <td><span>Pas un pré-cancer canalaire direct</span> mais <span>marqueur de risque bilatéral diffus</span>. Classé dans les <strong>lésions bénignes à risque</strong> (à la différence du CCIS)</td>\n            <td><span>Exérèse</span> + <span>surveillance</span> rapprochée bilatérale</td>\n          </tr>\n          <tr>\n            <td><span>Papillome intra-canalaire</span></td>\n            <td>Prolifération épithéliale intra-canaliculaire. <span>Écoulement mamelonnaire parfois sanglant</span></td>\n            <td><span>Exérèse <span class=\"nc-pink\">chirurgicale</span></span> (sauf petite <span>lésion</span> totalement disparue après <span>macrobiopsie</span>)</td>\n          </tr>\n          <tr>\n            <td><span>Tumeur phyllode</span></td>\n            <td>Double composante fibro-épithéliale. <strong>Principal <span>diagnostic différentiel</span> de l'adénofibrome</strong>. Bénin à malin selon le <span>grade</span></td>\n            <td><span>Exérèse chirurgicale</span> recommandée</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Tumeurs malignes — typologie</h4>\n      <table>\n        <thead>\n          <tr><th>Type</th><th>Fréquence</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-red_bg\">Carcinome</span></span><span class=\"nc-red_bg\"> canalaire in situ</span> (CCIS)</strong></td>\n            <td>Non <span class=\"nc-red nc-bold\">infiltrant</span></td>\n            <td><span>Vrai pré-cancer</span>. Pas de <span class=\"nc-red nc-bold\">franchissement de la </span><span><span class=\"nc-red nc-bold\">membrane basale</span></span>, <span>risque métastatique nul</span>. <span><span class=\"nc-green_bg\">Évolution</span></span> possible en plusieurs années vers un cancer invasif. PEC : <span><span class=\"nc-pink nc-bold\">chirurgie</span></span><span class=\"nc-pink nc-bold\"> systématique</span> avec marge <span>≥ <span class=\"nc-pink nc-bold\">2 mm</span></span>, pas de traitement systémique.</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-yellow_bg\">Carcinome</span></span><span class=\"nc-yellow_bg\"> canalaire infiltrant</span></strong> (= <span class=\"nc-yellow_bg\">carcinome infiltrant non spécifique</span>)</td>\n            <td><span>~90 %</span></td>\n            <td>Forme la plus fréquente</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-orange_bg\">Carcinome</span></span><span class=\"nc-orange_bg\"> lobulaire infiltrant</span></strong></td>\n            <td><span>~10 %</span></td>\n            <td>Souvent <span>multifocal</span> ou <span>bilatéral</span>. Cellules infiltrant « en file indienne » (perte de l'<span>E-cadhérine</span>). Dissémination volontiers péritonéale.</td>\n          </tr>\n          <tr>\n            <td><strong>Formes rares</strong></td>\n            <td>—</td>\n            <td><span>Carcinome médullaire</span> (à évoquer pour BRCA), mucineux, tubuleux, papillaire, lymphomes, sarcomes, métastases intra-mammaires</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Sous-types moléculaires (sur tout cancer <span class=\"nc-red nc-bold\">infiltrant</span>)</h4>\n      <table>\n        <thead>\n          <tr><th>Sous-type</th><th>RH</th><th>HER2</th><th>Ki67</th><th>Traitement principal</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Luminal A</td><td><span>RO</span>+ / <span>RP</span> <span>≥ 20 %</span></td><td>Négatif</td><td><span>&lt; 20 %</span></td><td><span>Hormonothérapie</span></td></tr>\n          <tr><td>Luminal B</td><td>RO+ / <span>RP</span> &lt;<span> 20 %</span></td><td>Négatif</td><td><span>≥ 20 %</span></td><td><span class=\"nc-pink_bg\">Hormonothérapie</span> + <span><span class=\"nc-pink nc-bold\">chimiothérapie</span></span></td></tr>\n          <tr><td>HER2+ (<span>15 %</span>)</td><td>+ ou −</td><td>Positif</td><td>Mauvais <span>pronostic</span></td><td><span><span class=\"nc-pink nc-bold\">Trastuzumab</span></span> + <span><span class=\"nc-pink nc-bold\">chimiothérapie</span></span> ± <span class=\"nc-pink_bg\">hormonothérapie</span> si RH+</td></tr>\n          <tr><td><span class=\"nc-red nc-bold\">Triple négatif</span> (<span>15 %</span>)</td><td>Négatifs</td><td><span class=\"nc-red nc-bold\">Négatif</span></td><td>Très mauvais <span>pronostic</span></td><td><span><span class=\"nc-pink nc-bold\">Chimiothérapie</span> systématique</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span>Drapeau <span class=\"nc-red nc-bold\">rouge</span></span>.</strong> Ne pas confondre <span>CCIS</span> (<span><span class=\"nc-red_bg\">carcinome</span></span><span class=\"nc-red_bg\"> </span><em><span class=\"nc-red_bg\">canalaire</span></em><span class=\"nc-red_bg\"> in situ</span> — vrai pré-cancer, <span><span class=\"nc-pink nc-bold\">chirurgie</span></span><span class=\"nc-pink nc-bold\"> systématique</span>) et <span>CLIS</span> (<span class=\"nc-red_bg\">carcinome </span><em><span class=\"nc-red_bg\">lobulaire</span></em><span class=\"nc-red_bg\"> in situ</span> — classé dans les lésions bénignes à <span class=\"nc-green_bg nc-bold\">risque</span>, marqueur de <span class=\"nc-green_bg nc-bold\">risque</span> bilatéral). Le CCIS impose un traitement local complet ; le CLIS impose une <span>surveillance</span> rapprochée <span class=\"nc-blue_bg\">bilatérale</span>.</div></div>"},{"i":"cf0b5e722a00","n":312,"o":"312-11","u":"Examens complémentaires","t":"Connaître les principes du bilan d'extension d'un cancer du sein","q":"Que retenir concernant les principes du bilan d'extension d'un cancer du sein ?","a":"<div class=\"notion-course\"><p>Le <span><span class=\"nc-yellow_bg\">bilan d'extension</span></span> est indispensable avant le protocole thérapeutique du <span class=\"nc-red_bg\">cancer du sein</span> <strong><span class=\"nc-red nc-bold\">infiltrant</span></strong>. Il comprend un <strong>bilan loco-régional</strong> systématique, un <strong>bilan à distance</strong> ciblé selon le <span>stade</span> et un <strong><span>bilan préthérapeutique</span></strong> <span>biologique</span>. La <span>stadification</span> est résumée par le <span>TNM</span> (<span>cTNM</span> clinique, <span>pTNM</span> anatomopathologique, <span>ypTNM</span> après néoadjuvant).</p>\n      <h4>Bilan loco-régional (systématique)</h4>\n      <ul>\n        <li><span><span class=\"nc-blue_bg\">Mammographie bilatérale</span></span></li>\n        <li><span><span class=\"nc-blue_bg\">Échographie mammaire</span></span></li>\n        <li><span>Échographie axillaire</span> ± cytoponction d'<span>adénopathie</span> suspecte</li>\n      </ul>\n      <h4><span>IRM</span> mammaire — indications ciblées (rang C)</h4>\n      <table>\n        <thead>\n          <tr><th>Indication</th><th>Justification clinique</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-pink\">Oncoplastie majeure</span></span> (prothèse mammaire)</td><td>Mammographie/écho peu informatives</td></tr>\n          <tr><td>Femme <span>&lt; 40 ans</span></td><td><span class=\"nc-green\">Seins denses</span>, sensibilité mammo réduite</td></tr>\n          <tr><td><span class=\"nc-green\">Seins </span><span><span class=\"nc-green\">denses</span> ACR C/D</span> non évaluables</td><td>Densité masque les lésions en mammo</td></tr>\n          <tr><td><span>Carcinome lobulaire infiltrant</span></td><td>Volontiers <span>multifocal et bilatéral</span></td></tr>\n          <tr><td><span><span class=\"nc-orange\">Adénomégalie métastatique</span></span> sans anomalie mammo/écho</td><td>Recherche <span class=\"nc-green_bg\">tumeur</span> primitive mammaire occulte</td></tr>\n          <tr><td>Discordance radio-clinique sur la <span>taille tumorale</span></td><td>Préciser avant traitement conservateur</td></tr>\n          <tr><td>Avant <span><span class=\"nc-pink nc-bold\">chimiothérapie néoadjuvante</span></span></td><td>Bilan initial pour évaluation de la réponse</td></tr>\n          <tr><td>Recherche de tumeur primitive si imagerie <span class=\"nc-red nc-bold\">négative</span></td><td>Métastases révélatrices sans primitif évident</td></tr>\n        </tbody>\n      </table>\n      <h4>Bilan à distance — indications formelles (<span>carcinome</span> infiltrant)</h4>\n      <table>\n        <thead>\n          <tr><th>Situation</th><th>Bilan à distance</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Tumeurs <span>≥ 3 cm</span></td>\n            <td><span>Oui</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"nc-red_bg\">Tumeurs avec atteinte</span> <span><span class=\"nc-red_bg nc-bold\">cutanée</span></span>, <span><span class=\"nc-red_bg nc-bold\">musculaire</span></span> ou <span><span class=\"nc-red_bg nc-bold\">inflammatoire</span></span> (stades T4)</td>\n            <td>Oui</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-red_bg\">Envahissement</span></span><span class=\"nc-red_bg\"> ganglionnaire</span> <strong>N+</strong> (cytoponction ou post-<span>chirurgie</span>)</td>\n            <td>Oui</td>\n          </tr>\n          <tr>\n            <td><span class=\"nc-red_bg\">Signes d'appel cliniques de métastase</span></td>\n            <td>Oui</td>\n          </tr>\n          <tr>\n            <td>Tumeurs <strong>T2</strong> avec sous-type <span><span class=\"nc-red nc-bold\">triple négatif</span></span> ou <span>HER2+</span></td>\n            <td>Oui (selon collège de gynécologie)</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-orange_bg\">Carcinome in situ</span></span> (CCIS)</td>\n            <td><strong>Non</strong> — pas de risque de dissémination</td>\n          </tr>\n        </tbody>\n      </table>\n      <h4>Options techniques (hiérarchie selon disponibilité)</h4>\n      <ul>\n        <li><span>TEP-TDM au 18-FDG</span> ± <span>CA 15-3</span> + <span>ACE</span> — <strong>option préférée si disponible</strong></li>\n        <li><span><span class=\"nc-yellow_bg\">TDM TAP injectée</span></span> + <span>scintigraphie osseuse</span> ± <span><span class=\"nc-pink_bg\">CA 15-3</span></span> + <span><span class=\"nc-pink_bg\">ACE</span></span> — alternative</li>\n        <li><span>RX thoracique</span> + <span>écho abdominale</span> + <span>scintigraphie osseuse</span> — <span>à défaut</span> uniquement</li>\n        <li><span>IRM corps entier</span> chez la <span>femme enceinte</span> (<span>irradiation</span> <span>à éviter</span>)</li>\n      </ul>\n      <h4><span>Bilan préthérapeutique</span> (biologie)</h4>\n      <p><span>NFS</span>, <span>hémostase</span>, <span>calcémie</span>, <span>bilan hépatique</span>. Le <span>CA 15-3</span> est <span>optionnel</span> (peu sensible, peu spécifique, souvent <span class=\"nc-red nc-bold\">négatif</span> au diagnostic) — utile principalement au <span>suivi</span> de la <span class=\"nc-red nc-bold\">maladie métastatique</span>.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Pas de <span><span class=\"nc-yellow_bg\">bilan d'extension</span></span> dans le <strong>CCIS</strong> (<span class=\"nc-green_bg nc-bold\">risque</span> métastatique nul). Pour le cancer <span class=\"nc-red nc-bold\">infiltrant</span>, l'indication formelle repose sur la taille, le T, le N et le sous-type moléculaire. Le <span>carcinome lobulaire</span> a un bilan adapté (<span>TDM</span>/<span>TEP</span> en raison du tropisme péritonéal).</div></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d94181fb956fd58603b553de?pvs=204","reviewedAt":"2026-10-15","note":"Cours personnel, couleurs des passages Notion correspondants, corrections et parcours interactifs sourcés. Les compléments sont distingués des figures d’origine."}};
